/* ── Nomenclature: what every symbol in a module's equations stands for,
   plus one short paragraph on how those equations chain together. ───── */
const NOM = {};
Object.assign(NOM, {
'G-01': { f: 'The duty fixes the area, and A = \u03c0d\u2092LN\u209c turns that area into a tube count once you choose a tube diameter and length. The count sets the bundle diameter through the TEMA constants, the shell is the bundle plus the head clearance, and the shell diameter with the pitch and the baffle spacing fixes the cross-flow area and the equivalent diameter \u2014 the two numbers every shell-side heat-transfer correlation asks for.', s: [
 ['N_t', 'number of tubes in the bundle'], ['A', 'heat transfer area provided by the bundle, m\u00b2'],
 ['d_o', 'tube outside diameter, mm'], ['L', 'tube length between tubesheets, m'],
 ['D_b', 'bundle diameter \u2014 the circle enclosing the outermost tubes, mm'],
 ['D_s', 'shell inside diameter, mm \u2014 bundle plus head clearance'],
 ['K_1,\\ n_1', 'TEMA layout constants; they depend on the tube pattern and the number of tube passes'],
 ['p_t', 'tube pitch \u2014 centre-to-centre spacing, usually 1.25 d\u2092'],
 ['l_B', 'baffle spacing along the shell, m'], ['A_s', 'shell-side cross-flow area at the shell centreline, m\u00b2'],
 ['D_e', 'shell-side equivalent (hydraulic) diameter, m'] ] },
'G-02': { f: 'Everything starts with the flow parameter F_LV, which says whether the tray is vapour-loaded or liquid-loaded. That fixes the Souders\u2013Brown coefficient K\u2081, K\u2081 gives the flooding velocity, and the flooding velocity divided into the vapour volumetric flow gives the column area and diameter. The rest of the module then checks that the tray you just sized actually works hydraulically: weir crest, downcomer area and downcomer backup.', s: [
 ['u_f', 'flooding vapour velocity based on the net tray area, m/s'],
 ['K_1', 'Souders\u2013Brown capacity coefficient, read from the tray spacing and F_LV'],
 ['\\rho_L,\\ \\rho_V', 'liquid and vapour density, kg/m\u00b3'],
 ['F_{LV}', 'flow parameter \u2014 the ratio of liquid to vapour kinetic energy; small means vapour-loaded'],
 ['L_w,\\ V_w', 'liquid and vapour mass flow rates, kg/s'],
 ['h_w', 'weir height above the tray deck, mm'], ['h_{ow}', 'crest of liquid flowing over the weir, mm'],
 ['l_w', 'weir length, m'], ['A_{dc}', 'downcomer cross-sectional area, m\u00b2'],
 ['t_{dc}', 'liquid residence time in the downcomer, s \u2014 needs 3 s or more to disengage vapour'],
 ['h_{bc}', 'clear-liquid backup in the downcomer, mm \u2014 must stay below the tray spacing'],
 ['s', 'tray spacing, mm'] ] },
'G-03': { f: 'The Eckert correlation plays the same role here that Souders\u2013Brown plays for trays: F_LV and the packing factor give the flooding gas rate, you design at 70\u201380 % of it, and that fixes the diameter. Height comes from the other direction \u2014 the separation demands N theoretical stages, and each one costs one HETP of packing.', s: [
 ['u_f', 'gas velocity at flooding, m/s'], ['F_p', 'packing factor, m\u207b\u00b9 \u2014 a measured resistance number for the packing'],
 ['F_{LV}', 'flow parameter, the liquid-to-vapour loading ratio'],
 ['\\rho_L,\\ \\rho_V', 'liquid and vapour density, kg/m\u00b3'],
 ['\\mu_L,\\ \\mu_w', 'liquid viscosity and the water reference viscosity used to correct it'],
 ['g', 'gravitational acceleration, 9.81 m/s\u00b2'],
 ['Z', 'packed height, m'], ['N', 'theoretical stages the separation needs'],
 ['HETP', 'height equivalent to a theoretical plate \u2014 metres of packing per stage'],
 ['n_{drip}', 'distributor drip points per m\u00b2; too few and the packing never sees plug flow'] ] },
'G-04': { f: 'The one-foot method sizes each shell course from the hydrostatic head standing on it, so the bottom course is thickest and the courses step down the shell. Each course is designed twice \u2014 once for the product at its own specific gravity, once for the water hydrostatic test \u2014 and the thicker answer wins. Wind is a separate check: the overturning moment is compared against the resisting weight of the empty shell, which is why anchorage is governed by the empty tank, not the full one.', s: [
 ['t_d', 'design shell thickness for the course, mm'], ['t_t', 'hydrostatic-test thickness for the same course, mm'],
 ['D', 'tank diameter, m'], ['H', 'design liquid height above the bottom of the course, m'],
 ['G', 'specific gravity of the stored liquid (water = 1)'],
 ['S_d,\\ S_t', 'allowable stress for the design and the hydrostatic-test case, MPa'],
 ['CA', 'corrosion allowance added to every course, mm'],
 ['M_{wind}', 'overturning moment about the tank base from wind, N\u00b7m'],
 ['\\rho_a', 'air density, 1.225 kg/m\u00b3'], ['u', 'design wind speed, m/s'],
 ['C_s', 'shape factor for the cylinder, 0.7'], ['W_{shell}', 'shell weight resisting overturning, N'] ] },
'G-05': { f: 'One equation drives the whole module: flow through a growing cake. Integrated at constant pressure it becomes a straight line of t/V against V \u2014 the slope carries the cake resistance and the intercept the cloth resistance, so a single filtration run measures both. Because the cake keeps thickening, filtering longer always gives less filtrate per minute, and trading that against the fixed dump-and-wash time gives an optimum cycle.', s: [
 ['V', 'volume of filtrate collected, m\u00b3'], ['t', 'filtration time, s'],
 ['A', 'filter area, m\u00b2'], ['\\Delta P', 'pressure drop across cake and cloth together, Pa'],
 ['\\mu', 'filtrate viscosity, Pa\u00b7s'],
 ['\\alpha', 'specific cake resistance, m/kg \u2014 how hard the cake is to push liquid through'],
 ['c', 'mass of dry cake deposited per unit volume of filtrate, kg/m\u00b3'],
 ['R_m', 'filter medium (cloth) resistance, m\u207b\u00b9'],
 ['\\alpha_0,\\ n', 'resistance at unit pressure and the compressibility index; n = 0 is an incompressible cake'],
 ['t_f', 'filtration time in the cycle, s'], ['t_{dump}', 'fixed downtime to discharge and wash, s'],
 ['t_{cycle,opt}', 'cycle time that maximises filtrate per hour, s'] ] },
'G-06': { f: 'Rotary dryers are sized volumetrically rather than by surface area, because nobody can measure the surface of a tumbling solid. The gas mass velocity gives a volumetric coefficient U_va, the duty divided by U_va\u0394T_lm gives the drum volume, and the number of transfer units checks that the length-to-diameter ratio lands in the 4\u201310 range real dryers use.', s: [
 ['U_va', 'volumetric heat transfer coefficient, W/m\u00b3\u00b7K \u2014 coefficient and area lumped together'],
 ['G', 'gas mass velocity through the drum, kg/m\u00b2\u00b7s'], ['D', 'drum diameter, m'], ['L', 'drum length, m'],
 ['V', 'drum volume, m\u00b3'], ['Q', 'heat duty \u2014 sensible heating plus evaporation, W'],
 ['\\Delta T_{lm}', 'log-mean temperature difference between gas and solids, K'],
 ['N_t', 'number of transfer units \u2014 how many times the gas is used up'],
 ['T_{g1},\\ T_{g2}', 'gas temperature in and out, \u00b0C'], ['T_{s1},\\ T_{s2}', 'solids temperature in and out, \u00b0C'],
 ['\\theta', 'solids residence time in the drum, min'] ] },
'G-07': { f: 'Two independent criteria size a flare. The tip diameter comes from the exit Mach number \u2014 too fast and the flame blows off, too slow and it burns back. The height comes from radiation: the flame length and tilt place a radiating centre in space, the inverse-square law gives the intensity at grade, and the stack is raised until that intensity meets the API 521 limit for the exposure you are protecting.', s: [
 ['d_{tip}', 'flare tip diameter, m'], ['W', 'relief mass flow to the flare, kg/s'],
 ['\\rho', 'gas density at the tip, kg/m\u00b3'], ['u', 'gas velocity leaving the tip, m/s'],
 ['Ma', 'exit Mach number \u2014 0.2 for continuous flow, up to 0.5 on emergency relief'],
 ['k', 'ratio of specific heats, c_p/c_v'], ['R', 'universal gas constant, 8.314 J/mol\u00b7K'],
 ['T', 'gas temperature at the tip, K'], ['M', 'molar mass of the relieving gas, kg/mol'],
 ['K', 'radiant heat flux reaching the receiver, kW/m\u00b2'],
 ['\\tau', 'atmospheric transmissivity \u2014 the fraction that gets through humid air'],
 ['F', 'fraction of the combustion heat radiated, typically 0.15\u20130.3'],
 ['Q', 'total heat release of the flame, kW'], ['D', 'distance from the flame centre to the receiver, m'],
 ['L_f', 'flame length, m'], ['\\theta', 'flame tilt angle from vertical, set by the crosswind'],
 ['u_{wind}', 'crosswind speed, m/s'] ] },
'G-08': { f: 'An evaporator train buys steam economy with temperature. The total driving force is fixed once and for all by the steam and the condenser, so every effect you add divides the same \u0394T into smaller pieces; each effect needs more area for less driving force while the steam bill falls roughly as 1/n. Capital rising and steam falling is what puts a minimum in the annualised cost, and that minimum is the design.', s: [
 ['n_{eff}', 'number of effects in the train'],
 ['\\text{economy}', 'kilograms of water evaporated per kilogram of live steam'],
 ['\\Delta T_i', 'temperature driving force available to effect i, K'],
 ['T_{steam}', 'live steam temperature into the first effect, \u00b0C'],
 ['T_{cond}', 'condenser temperature after the last effect, \u00b0C'],
 ['BPE_i', 'boiling-point elevation of the liquor in effect i, K \u2014 driving force lost to dissolved solids'],
 ['A_i', 'heat transfer area of effect i, m\u00b2'], ['Q_i', 'heat duty of effect i, W'],
 ['U_i', 'overall coefficient in effect i, W/m\u00b2\u00b7K \u2014 falls down the train as the liquor thickens'] ] },
'Z-01': { f: 'The Ergun equation is two pressure drops added together: a viscous term linear in velocity and an inertial term quadratic in it. Which one dominates is decided by the particle Reynolds number \u2014 below about 10 the bed is pure Blake\u2013Kozeny, above about 1000 pure Burke\u2013Plummer. Voidage is the violent variable in both: the \u03b5\u00b3 in the denominator means a 5 % packing change moves the pressure drop by 30 %.', s: [
 ['\\Delta P/L', 'pressure gradient down the bed, Pa/m'],
 ['\\mu', 'fluid viscosity, Pa\u00b7s'], ['\\rho', 'fluid density, kg/m\u00b3'],
 ['u', 'superficial velocity \u2014 the velocity the empty tower would see, m/s'],
 ['\\varepsilon', 'bed voidage \u2014 the fraction of the bed volume that is empty'],
 ['\\phi', 'sphericity \u2014 1 for a sphere, ~0.3 for a Raschig ring'],
 ['d_p', 'particle diameter, m'],
 ['Re_p', 'particle Reynolds number \u2014 the ratio of inertial to viscous forces'],
 ['f_p', 'packed-bed friction factor'] ] },
'Z-02': { f: 'Minimum fluidisation is the velocity at which the drag on the bed equals its buoyant weight, so the pressure drop stops climbing and goes flat \u2014 that plateau is the bed weighing itself. Setting the Ergun pressure drop equal to that weight gives u_mf; the Wen\u2013Yu correlation is the same result packaged in the Archimedes number. Above u_mf a liquid bed expands smoothly by Richardson\u2013Zaki, while a gas bed sends the excess into bubbles instead.', s: [
 ['u_{mf}', 'minimum fluidisation velocity, m/s'], ['u_t', 'terminal (free-fall) velocity of a single particle, m/s'],
 ['\\varepsilon_{mf}', 'bed voidage at minimum fluidisation, typically 0.4\u20130.5'],
 ['\\varepsilon', 'voidage of the expanded bed'],
 ['\\rho_s,\\ \\rho', 'solid and fluid density, kg/m\u00b3'],
 ['g', 'gravitational acceleration, 9.81 m/s\u00b2'], ['d_p', 'particle diameter, m'], ['\\mu', 'fluid viscosity, Pa\u00b7s'],
 ['Ar', 'Archimedes number \u2014 buoyant weight against viscous forces; the dimensionless particle size'],
 ['Re_{mf}', 'Reynolds number at minimum fluidisation'],
 ['n', 'Richardson\u2013Zaki expansion index, from 4.65 (Stokes) to 2.4 (inertial)'],
 ['L_{mf},\\ L', 'bed height at minimum fluidisation and when expanded, m'] ] },
'Z-03': { f: 'Geldart\u2019s map is a two-axis classification: particle size across, density difference up. Those two numbers decide whether a powder aerates before it bubbles (A), bubbles the instant it fluidises (B), refuses to fluidise at all because cohesion beats drag (C), or spouts and blows through (D). Everything downstream \u2014 bubbling behaviour, entrainment, whether the bed slugs \u2014 follows from which quadrant you land in.', s: [
 ['d_p', 'mean particle diameter, \u00b5m'],
 ['\\rho_s - \\rho', 'density difference between solid and gas, kg/m\u00b3 \u2014 the vertical axis of the map'],
 ['\\mu', 'gas viscosity, Pa\u00b7s'], ['g', 'gravitational acceleration'],
 ['u_{mf}', 'minimum fluidisation velocity, m/s'],
 ['u_{mb}', 'minimum bubbling velocity \u2014 above u_mf only for group A powders'],
 ['u_{ms}', 'minimum slugging velocity, m/s'],
 ['F_{45}', 'mass fraction of the powder finer than 45 \u00b5m; fines push a powder towards group A behaviour'] ] },
'Z-04': { f: 'Above a bubbling bed the splash zone throws solids upward; they fall back until the freeboard is tall enough that only the genuinely elutriable fines survive. That height is the TDH. Each size cut has its own elutriation constant, so entrainment is summed cut by cut, and whatever leaves is then offered to the cyclone, whose grade-efficiency curve decides what is recovered and what goes to the stack.', s: [
 ['TDH', 'transport disengaging height \u2014 freeboard above which entrainment stops falling, m'],
 ['u_0', 'superficial gas velocity through the bed, m/s'],
 ['G_s', 'entrainment flux leaving the freeboard, kg/m\u00b2\u00b7s'],
 ['\\kappa_i', 'elutriation rate constant for size cut i, kg/m\u00b2\u00b7s'],
 ['x_i', 'mass fraction of cut i in the bed'], ['A', 'bed cross-sectional area, m\u00b2'],
 ['E_i', 'entrainment rate of cut i, kg/s'], ['a', 'freeboard decay constant, m\u207b\u00b9'],
 ['\\eta_{cyc}', 'overall cyclone collection efficiency'],
 ['d_{50}', 'cyclone cut size \u2014 the diameter collected with 50 % efficiency, \u00b5m'],
 ['d_p', 'particle diameter, \u00b5m'] ] },
'Z-05': { f: 'The two beds are compared on the same reaction. A fixed bed is plug flow with a diffusion-limited pellet, so conversion follows an exponential in \u03b7kL/u \u2014 excellent contacting, but big pellets waste catalyst and the Ergun pressure drop climbs with the square of velocity. A fluidised bed uses powder, so \u03b7 \u2248 1, but gas bypasses in bubbles and the exchange coefficient K_f caps the conversion no matter how much catalyst you add.', s: [
 ['X', 'fractional conversion of the reactant leaving the bed'],
 ['\\eta', 'pellet effectiveness factor \u2014 actual rate divided by the rate with no diffusion limit'],
 ['k', 'first-order rate constant on the catalyst, s\u207b\u00b9'],
 ['\\varepsilon', 'bed voidage'], ['L', 'bed height, m'], ['u', 'superficial gas velocity, m/s'],
 ['K_f', 'bubble-to-emulsion mass-transfer coefficient, s\u207b\u00b9 \u2014 the fluid bed\u2019s bypass penalty'],
 ['\\varepsilon_{mf}', 'voidage at minimum fluidisation'], ['L_f', 'expanded height of the fluidised bed, m'],
 ['\\Delta P', 'bed pressure drop, Pa'], ['\\rho_s,\\ \\rho', 'catalyst and gas density, kg/m\u00b3'],
 ['\\Delta T_{ad}', 'adiabatic temperature rise if the bed ran with no heat removal, K'],
 ['\\Delta H_r', 'heat of reaction, J/mol'], ['C_{A0}', 'inlet reactant concentration, mol/m\u00b3'],
 ['c_p', 'gas heat capacity, J/kg\u00b7K'] ] },
'Z-06': { f: 'A single roasting particle converts on a clean shrinking-core clock: it is finished at t = \u03c4. But solids in a fluidised bed are perfectly mixed, so their residence times are exponentially distributed \u2014 some particles leave almost immediately. Averaging the single-particle curve over that distribution is what flattens the conversion curve, and staging beds in series is the only cure, because N tanks in series narrows the distribution back towards plug flow.', s: [
 ['X_B', 'conversion of the solid reactant B in a single particle at time t'],
 ['\\bar X_B', 'mean conversion of the solids leaving the bed'],
 ['t', 'time a particle has spent in the bed, s'],
 ['\\bar t', 'mean solids residence time \u2014 bed inventory divided by feed rate, s'],
 ['E(t)', 'exit-age distribution \u2014 the fraction of solids leaving with age t'],
 ['\\tau', 'time for complete conversion of one particle, s'],
 ['N', 'number of fluidised stages in series'],
 ['X_{B,N}', 'mean conversion after N stages'] ] },
'Y-01': { f: 'Crystallisation yield is a mass balance on the solute with the solubility curve supplying the endpoint: whatever the mother liquor cannot hold at the discharge temperature must appear as crystals. Cooling moves you down the solubility curve, evaporating solvent moves you up in concentration, and both routes are just different ways of driving the concentration above c*. Supersaturation \u03c3 is the distance above the curve \u2014 the driving force for everything in the modules that follow.', s: [
 ['y', 'yield of crystals, kg'], ['R', 'hydrate ratio \u2014 molar mass of the hydrate over the anhydrous salt'],
 ['W_0', 'mass of solvent in the feed, kg'],
 ['c_0,\\ c_1', 'solute concentration in the feed and in the final mother liquor, kg per kg solvent'],
 ['E', 'solvent evaporated during the operation, kg'],
 ['c', 'actual solute concentration in solution'], ['c^*', 'solubility \u2014 the concentration at saturation'],
 ['\\sigma', 'relative supersaturation, (c \u2212 c*)/c* \u2014 the driving force'],
 ['S', 'supersaturation ratio c/c*'],
 ['\\Delta H_{cryst}', 'heat released on crystallisation, kJ/kg'],
 ['q', 'cooling duty, kW'], ['c_p', 'liquor heat capacity, kJ/kg\u00b7K'] ] },
'Y-02': { f: 'Nucleation is a competition between the free energy you gain by making solid and the energy you pay for new surface, which is why the rate is an exponential in 1/(ln S)\u00b2 \u2014 essentially zero, then suddenly enormous. Real crystallisers rarely reach that limit because secondary nucleation from existing crystals starts far earlier. The metastable zone width you can measure is the practical consequence: cool faster and you overshoot deeper before anything appears.', s: [
 ['J', 'primary nucleation rate, nuclei per m\u00b3 per second'],
 ['A', 'pre-exponential factor, conventionally 10\u00b3\u2070 m\u207b\u00b3s\u207b\u00b9'],
 ['\\gamma', 'crystal\u2013solution interfacial tension, J/m\u00b2 \u2014 the cost of new surface'],
 ['v', 'molecular volume of the solute, m\u00b3'], ['k', 'Boltzmann constant, 1.381\u00d710\u207b\u00b2\u00b3 J/K'],
 ['T', 'absolute temperature, K'], ['S', 'supersaturation ratio c/c*'],
 ['B_0', 'secondary nucleation rate, nuclei per m\u00b3 per second'],
 ['k_b', 'secondary nucleation rate constant'], ['\\sigma', 'relative supersaturation'],
 ['b', 'supersaturation order in the nucleation law, typically 1\u20132'],
 ['M_T', 'magma density \u2014 crystal mass per volume of slurry, kg/m\u00b3'],
 ['j', 'magma-density exponent, typically 1'],
 ['\\Delta T_{max}', 'metastable zone width \u2014 how far you can undercool before nuclei appear, K'],
 ['m', 'N\u00fdvlt exponent relating zone width to cooling rate'],
 ['R_c', 'cooling rate, K/h'], ['L_c', 'critical nucleus size, m \u2014 smaller clusters redissolve'] ] },
'Y-03': { f: 'The population balance tracks crystals as they grow through size space rather than tracking mass. For a perfectly mixed continuous crystalliser it collapses to a single straight line on a semi-log plot: the intercept is the nuclei density B\u2080/G, the slope is \u22121/G\u03c4. That means one CSD measurement gives you both kinetic parameters, and the whole size distribution is fixed by the product G\u03c4 \u2014 the dominant size is exactly 3G\u03c4.', s: [
 ['n', 'population density \u2014 crystals per unit size per unit slurry volume, m\u207b\u2074'],
 ['n^0', 'nuclei population density at zero size, m\u207b\u2074 \u2014 equals B\u2080/G'],
 ['G', 'linear growth rate, m/s'], ['L', 'crystal size, \u00b5m'],
 ['\\tau', 'mean residence time in the crystalliser, s'],
 ['L_{dom}', 'dominant size \u2014 the peak of the mass distribution, 3G\u03c4'],
 ['L_{50}', 'median size by mass, \u00b5m'],
 ['M_T', 'magma density, kg of crystals per m\u00b3 of slurry'],
 ['k_v', 'volume shape factor \u2014 0.52 for a rounded crystal, \u03c0/6 for a sphere'],
 ['\\rho_c', 'crystal density, kg/m\u00b3'],
 ['CV', 'coefficient of variation of the distribution \u2014 always 50 % for an ideal MSMPR'] ] },
'Y-04': { f: 'This is the population balance run backwards. Sieve the product, plot ln n against L, and the straight portion gives G from the slope and n\u2070 from the intercept. Repeat at several supersaturations and the growth and nucleation power laws fall out of a log\u2013log regression \u2014 and the value of g is the diagnosis: near 1 means diffusion control at the crystal face, near 2 means surface integration.', s: [
 ['n', 'population density from the sieve analysis, m\u207b\u2074'],
 ['n^0', 'nuclei population density \u2014 the intercept of the regression line'],
 ['L', 'crystal size, \u00b5m'], ['G', 'growth rate from the slope \u22121/G\u03c4, m/s'],
 ['\\tau', 'residence time, s'], ['k_g', 'growth rate coefficient'],
 ['\\sigma', 'relative supersaturation'],
 ['g', 'growth order \u2014 \u22481 diffusion-controlled, \u22482 surface-integration-controlled'],
 ['B_0', 'nucleation rate, m\u207b\u00b3s\u207b\u00b9 \u2014 recovered as n\u2070G'],
 ['k_b', 'nucleation rate coefficient'], ['b', 'supersaturation order for nucleation'],
 ['M_T', 'magma density, kg/m\u00b3'], ['j', 'magma-density exponent'] ] },
'Y-05': { f: 'A batch cooling crystalliser has one real enemy: nucleating a second crop halfway through. Seeds provide surface area, that area consumes supersaturation as it grows, and the growing crystals provide more area still \u2014 so the safe cooling rate is slow at the start and accelerates. Natural cooling does exactly the opposite, which is why it spikes the supersaturation early and showers fines.', s: [
 ['c', 'solute concentration in solution'], ['t', 'batch time, h'],
 ['k_g,\\ g', 'growth coefficient and order in G = k_g\u03c3\u1d4d'],
 ['\\sigma', 'relative supersaturation'], ['M_s', 'mass of seed charged, kg'],
 ['L_s', 'mean seed size, \u00b5m'], ['M_g', 'mass grown onto the seed, kg'],
 ['A_s', 'surface area of the seed charge, m\u00b2 \u2014 what consumes the supersaturation'],
 ['\\rho_c', 'crystal density, kg/m\u00b3'], ['k_v,\\ k_a', 'volume and area shape factors'],
 ['T_0,\\ T', 'starting and current batch temperature, \u00b0C'],
 ['\\Delta t_b', 'total batch cooling time, h'], ['L', 'crystal size, \u00b5m'] ] },
'Y-06': { f: 'Evaporative and antisolvent crystallisation use the same yield balance as cooling \u2014 only the mechanism for making the solution supersaturated changes. Boiling removes solvent, so the concentration climbs to meet a fixed solubility; adding an antisolvent leaves the concentration alone and pushes the solubility down to meet it. Both meet at the same place, and the choice is an energy-against-solvent-recovery argument.', s: [
 ['y', 'crystal yield, kg'], ['R', 'hydrate ratio'], ['W_0', 'feed solvent mass, kg'],
 ['c_0,\\ c_1', 'feed and final mother-liquor concentration'],
 ['E', 'solvent evaporated, kg'],
 ['x_{as}', 'antisolvent mass fraction in the final mixture'],
 ['k_{as}', 'solubility-depression constant \u2014 how steeply the antisolvent kills solubility'],
 ['n_{eff}', 'number of evaporator effects used to supply the boil-up'],
 ['\\sigma', 'relative supersaturation generated'] ] },
'Y-07': { f: 'Sizing is a residence-time argument: the production rate and the magma density fix the slurry volume, and the residence time fixes what size that volume can grow. Fines destruction is the scale-up trick \u2014 withdraw the small crystals, dissolve them, return the liquor, and the surviving crystals get all the growth, so the dominant size rises steeply with the fines ratio. The limit is the impeller: tip speed breaks crystals as fast as growth makes them.', s: [
 ['V', 'active crystalliser volume, m\u00b3'], ['m_{prod}', 'crystal production rate, kg/h'],
 ['\\tau', 'mean residence time, h'], ['M_T', 'magma density, kg/m\u00b3'],
 ['L_{dom}', 'dominant crystal size, \u00b5m'], ['G', 'growth rate, \u00b5m/min'],
 ['R_f', 'fines destruction ratio \u2014 fines recycle flow divided by product flow'],
 ['u_{tip}', 'impeller tip speed, m/s \u2014 above ~4 m/s attrition dominates'],
 ['N', 'agitator speed, rev/s'], ['D_i', 'impeller diameter, m'] ] },
'P-01': { f: 'Joback estimation is a chain: count the functional groups in the structure, sum their contributions to get the normal boiling point, then feed T_b into the critical-property correlations. T_c and P_c plus the boiling point give the acentric factor through Lee\u2013Kesler, and those three constants are all any cubic equation of state or corresponding-states correlation in the rest of the tool needs.', s: [
 ['T_b', 'normal boiling point at 1 atm, K'],
 ['n_i', 'number of times Joback group i appears in the molecule'],
 ['\\Delta T_{b,i}', 'group i\u2019s tabulated contribution to the boiling point, K'],
 ['T_c', 'critical temperature, K'], ['P_c', 'critical pressure, bar'],
 ['\\Delta T_{c,i},\\ \\Delta P_{c,i}', 'group contributions to the critical constants'],
 ['n_A', 'number of atoms in the molecule'],
 ['\\omega', 'acentric factor \u2014 how far the molecule departs from a simple spherical fluid'],
 ['T_{br}', 'reduced boiling point, T_b/T_c'],
 ['P_{br}', 'reduced pressure at the boiling point, 1 atm / P_c'],
 ['A,\\ B,\\ C', 'Antoine constants regressed from the estimated vapour-pressure curve'],
 ['P^{sat}', 'saturation (vapour) pressure, bar'] ] },
'P-02': { f: 'Two compounds side by side answer one question: can a column separate them? Relative volatility is the ratio of their vapour pressures, so it falls straight out of the two Antoine curves, and it changes with temperature \u2014 which is why the operating pressure of a column is a separation decision, not just a mechanical one. The mixture rules below it build pseudocritical constants so the pair can be treated as one fluid by an equation of state.', s: [
 ['\\alpha_{12}', 'relative volatility \u2014 the ratio of K-values; 1.0 means no separation is possible'],
 ['P_1^{sat},\\ P_2^{sat}', 'pure-component vapour pressures at the system temperature, bar'],
 ['K_i', 'K-value of component i \u2014 y_i/x_i, its tendency to be in the vapour'],
 ['P', 'system pressure, bar'], ['y_i', 'mole fraction of i in the vapour'],
 ['T_{ci},\\ P_{ci}', 'critical constants of pure component i'],
 ['T_{cm},\\ P_{cm}', 'pseudocritical constants of the mixture (Kay\u2019s rule)'],
 ['M_i,\\ M_m', 'molar mass of component i and of the mixture, g/mol'] ] }
});

Object.assign(NOM, {
'R-01': { f: 'A reversible reaction does not run to completion \u2014 it runs to the point where the forward and reverse rates cancel, and that point is fixed by the equilibrium constant alone. The rate constants only decide how long you wait to get there; the composition you arrive at is thermodynamics. That is why raising the temperature of an exothermic reversible reaction speeds you up but lowers the prize.', s: [
 ['C_A,\\ C_B', 'concentration of reactant A and product B, mol/L'],
 ['C_{A0}', 'initial concentration of A, mol/L'],
 ['t', 'reaction time, min'],
 ['k_1', 'forward rate constant, min\u207b\u00b9'], ['k_2', 'reverse rate constant, min\u207b\u00b9'],
 ['K', 'equilibrium constant, k\u2081/k\u2082 \u2014 sets where the reaction stops'],
 ['X_{eq}', 'equilibrium conversion \u2014 the ceiling no residence time can beat'] ] },
'R-02': { f: 'When the product you want is an intermediate, time is a trade: too little and you have not made it, too much and you have destroyed it. The B curve therefore has a maximum, and the optimum time is set purely by the ratio k\u2082/k\u2081. If the second step is fast relative to the first, the peak is low and early \u2014 the reason such schemes are often run in a short-contact-time reactor and quenched.', s: [
 ['C_A,\\ C_B,\\ C_C', 'concentrations of reactant A, intermediate B and final product C, mol/L'],
 ['C_{A0}', 'initial concentration of A, mol/L'],
 ['k_1', 'rate constant for A \u2192 B, min\u207b\u00b9'], ['k_2', 'rate constant for B \u2192 C, min\u207b\u00b9'],
 ['t', 'reaction time, min'],
 ['t_{opt}', 'time at which the intermediate peaks, min'],
 ['C_{B,max}', 'the highest concentration of B the scheme can ever reach'] ] },
'R-03': { f: 'With two reactions competing for the same reactant, selectivity depends only on the difference in their reaction orders. If the desired reaction has the higher order, keep the concentration high \u2014 batch or plug flow, no dilution. If it has the lower order, keep the concentration low \u2014 a CSTR, a semi-batch feed, a diluent. The reactor choice follows from the sign of \u03b1 \u2212 \u03b2 and nothing else.', s: [
 ['r_D,\\ r_U', 'rate of the desired and the undesired reaction, mol/L\u00b7min'],
 ['k_D,\\ k_U', 'rate constants of the two reactions'],
 ['C_A', 'reactant concentration, mol/L'],
 ['\\alpha', 'reaction order of the desired path'], ['\\beta', 'reaction order of the undesired path'],
 ['S_{D/U}', 'instantaneous selectivity \u2014 desired formed per undesired formed'],
 ['N_D,\\ N_U', 'moles of desired and undesired product accumulated'] ] },
'R-04': { f: 'Plot the inverse rate against conversion and the two reactor types become two areas on the same graph: the PFR is the area under the curve, the CSTR is the rectangle at the exit conversion. For normal kinetics the rate falls as conversion rises, so the rectangle is always the larger \u2014 that is the whole argument for plug flow, and it gets worse the higher the conversion you demand.', s: [
 ['V_{PFR},\\ V_{CSTR}', 'reactor volume needed by each type, L'],
 ['F_{A0}', 'molar feed rate of A, mol/min'],
 ['X', 'fractional conversion of A'],
 ['-r_A', 'rate of consumption of A, mol/L\u00b7min'],
 ['F_{A0}/(-r_A)', 'the plotted ordinate \u2014 its area is a volume'],
 ['C_A,\\ C_{A0}', 'reactant concentration at the exit and in the feed, mol/L'],
 ['\\varepsilon', 'expansion factor \u2014 the fractional volume change on complete conversion'] ] },
'R-05': { f: 'Two curves on one temperature axis: heat generated by the reaction, which is S-shaped because the Arrhenius rise eventually runs out of reactant, and heat removed by the coolant, which is a straight line. Steady states are where they cross. Three crossings means the reactor has two stable operating points with an unstable one between them \u2014 and a small change in feed temperature can make the middle and upper states collide and the reactor ignite.', s: [
 ['Q_g', 'heat generated by the reaction, W'], ['Q_r', 'heat removed by the coolant and the feed, W'],
 ['\\Delta H_r', 'heat of reaction, J/mol \u2014 negative for exothermic'],
 ['F_{A0}', 'molar feed rate of A, mol/s'], ['X', 'conversion at temperature T'],
 ['T', 'reactor temperature, K'], ['T_0', 'feed temperature, K'], ['T_c', 'coolant temperature, K'],
 ['UA', 'heat-transfer coefficient times jacket area, W/K \u2014 the slope of the removal line'],
 ['C_p', 'feed heat capacity, J/mol\u00b7K'], ['\\tau', 'mean residence time, s'],
 ['k,\\ k_0', 'rate constant and its Arrhenius pre-exponential'],
 ['E_a', 'activation energy, J/mol'], ['R', 'gas constant, 8.314 J/mol\u00b7K'] ] },
'R-06': { f: 'Two penalties act at once down a catalytic bed. Inside each pellet, diffusion cannot keep up with reaction, so only part of the catalyst is used \u2014 that is the Thiele modulus and the effectiveness factor. Along the bed, friction eats the pressure, and since gas concentration follows pressure, the rate falls as you go. Bigger pellets fix the pressure drop and wreck the effectiveness; the design is the compromise between them.', s: [
 ['\\phi', 'Thiele modulus \u2014 reaction rate compared with diffusion rate inside the pellet'],
 ['R_p', 'pellet radius, m'], ['k', 'intrinsic rate constant, s\u207b\u00b9'],
 ['D_e', 'effective diffusivity inside the pellet pores, m\u00b2/s'],
 ['\\eta', 'effectiveness factor \u2014 fraction of the catalyst that is actually working'],
 ['X', 'conversion'], ['W', 'catalyst mass down the bed, kg'],
 ['F_{A0}', 'molar feed rate of A, mol/s'], ['C_{A0}', 'inlet concentration, mol/m\u00b3'],
 ['\\varepsilon', 'bed voidage'],
 ['\\alpha', 'Ergun pressure-drop parameter, kg\u207b\u00b9'],
 ['P,\\ P_0', 'local and inlet pressure, bar'] ] },
'R-07': { f: 'Before trusting a measured rate you have to prove it is a rate and not a transport measurement. Each criterion isolates one resistance \u2014 Weisz\u2013Prater for pore diffusion, Carberry for the external film, Mears for the bed \u2014 and each is a dimensionless ratio of an observed rate to the transport rate available. Pass all of them and the kinetics are intrinsic; fail one and the number you fitted belongs to the apparatus, not the catalyst.', s: [
 ['\\Phi_{WP}', 'Weisz\u2013Prater criterion; below 0.3 pore diffusion is not limiting'],
 ['r_v', 'observed volumetric rate, mol/m\u00b3\u00b7s'], ['R_p', 'pellet radius, m'],
 ['D_e', 'effective pore diffusivity, m\u00b2/s'], ['C_s', 'concentration at the pellet surface, mol/m\u00b3'],
 ['C_b', 'concentration in the bulk gas, mol/m\u00b3'],
 ['\\phi', 'Thiele modulus'], ['\\eta', 'effectiveness factor'],
 ['Ca', 'Carberry number \u2014 external film resistance; below 0.05 the film is clear'],
 ['k_f', 'external mass-transfer coefficient, m/s'],
 ['Sh,\\ Re', 'Sherwood and Reynolds numbers for the pellet'],
 ['M_h', 'Mears criterion for heat transport through the bed'],
 ['\\Delta H_r', 'heat of reaction, J/mol'], ['E_a', 'activation energy, J/mol'],
 ['h_f', 'film heat transfer coefficient, W/m\u00b2\u00b7K'],
 ['\\lambda_p', 'pellet thermal conductivity, W/m\u00b7K'],
 ['\\Delta T_{max}', 'largest possible temperature rise inside the pellet, K'],
 ['d_p', 'pellet diameter, m'], ['L', 'bed length, m'] ] },
'R-08': { f: 'The residence-time distribution is what a tracer pulse tells you about mixing without opening the vessel. Its mean is the residence time, its variance is the mixing \u2014 zero variance is plug flow, a variance equal to \u03c4\u00b2 is a perfect stirred tank, and everything real is in between. Fitting N tanks in series reduces the whole curve to one number, and that number is enough to predict conversion for a first-order reaction.', s: [
 ['E(\\theta)', 'exit-age distribution \u2014 the fraction of fluid leaving with dimensionless age \u03b8'],
 ['\\theta', 'dimensionless time, t/\u03c4'], ['\\tau', 'mean residence time, V/Q'],
 ['N', 'number of equal stirred tanks in series that reproduce the measured curve'],
 ['\\sigma^2', 'variance of the distribution \u2014 the measure of how much mixing there is'],
 ['Pe', 'P\u00e9clet number for the dispersion model; large means near plug flow'],
 ['k', 'first-order rate constant, s\u207b\u00b9'],
 ['X', 'conversion predicted from the distribution'] ] },
'R-09': { f: 'Michaelis\u2013Menten is a saturating rate law: at low substrate the enzyme is idle and the rate is first order; at high substrate every active site is occupied and the rate flattens at V_max. K_m is the substrate concentration at half of V_max, so it measures affinity. Inhibitors are diagnosed by which of the two constants they move \u2014 competitive raises K_m, uncompetitive lowers both, and that is what the Lineweaver\u2013Burk lines show.', s: [
 ['v', 'reaction velocity, mmol/L\u00b7min'],
 ['V_{max}', 'maximum velocity when every active site is saturated'],
 ['S', 'substrate concentration, mmol/L'], ['S_0', 'initial substrate concentration'],
 ['K_m', 'Michaelis constant \u2014 substrate concentration giving half of V_max; low means high affinity'],
 ['I', 'inhibitor concentration, mmol/L'],
 ['K_{ic}', 'competitive inhibition constant \u2014 inhibitor binding the free enzyme'],
 ['K_{iu}', 'uncompetitive inhibition constant \u2014 inhibitor binding the enzyme\u2013substrate complex'],
 ['t', 'reaction time, min'] ] },
'C-01': { f: 'First-order plus dead time is the model almost every industrial loop is tuned on, because three numbers describe nearly any self-regulating process: how far it moves, how fast, and how long before it starts. Dead time is the villain \u2014 gain and time constant are easy to control around, but \u03b8 is information you simply do not have yet, and the ratio \u03b8/\u03c4 is what decides how hard the loop can be pushed.', s: [
 ['G_p(s)', 'process transfer function \u2014 output response per unit input in the Laplace domain'],
 ['K_p', 'process gain \u2014 steady-state change in output per unit change in input'],
 ['\\tau', 'time constant \u2014 the time to reach 63.2 % of the final change'],
 ['\\theta', 'dead time \u2014 the delay before the output moves at all'],
 ['s', 'Laplace variable'], ['y(t)', 'process output against time'], ['t', 'time'],
 ['\\theta/\\tau', 'controllability ratio; above ~1 the loop is dead-time dominant and hard to tune'] ] },
'C-02': { f: 'Second-order behaviour appears whenever two lags interact, and the damping ratio decides the character of the response. Below 1 the loop overshoots and rings; at 1 it is as fast as it can be without overshoot; above 1 it is sluggish. Every number engineers actually quote \u2014 overshoot, decay ratio, peak time, settling time \u2014 is a closed-form function of \u03b6 alone.', s: [
 ['G(s)', 'second-order transfer function'], ['K_p', 'process gain'],
 ['\\tau', 'natural period of the system, time units'],
 ['\\zeta', 'damping ratio \u2014 <1 oscillatory, 1 critically damped, >1 overdamped'],
 ['OS', 'fractional overshoot above the final value'],
 ['DR', 'decay ratio \u2014 each peak divided by the one before; the classic target is 1/4'],
 ['T', 'period of the oscillation, time units'],
 ['t_p', 'time to the first peak'], ['t_s', 'settling time to within a 2 % band'] ] },
'C-03': { f: 'Every tuning rule here reads the same three FOPDT numbers and returns the same three controller settings; they differ only in how aggressive they are prepared to be. Ziegler\u2013Nichols aims for quarter-decay and is fast and twitchy; IMC and lambda tuning set a closed-loop time constant you choose, so you can trade speed for robustness explicitly. Integral time is almost always tied to the process time constant, and derivative to the dead time.', s: [
 ['K_c', 'controller gain \u2014 how hard the controller pushes per unit of error'],
 ['K_p', 'process gain from the step test'],
 ['\\tau', 'process time constant'], ['\\theta', 'process dead time'],
 ['\\tau_I', 'integral (reset) time \u2014 how long the controller takes to remove offset'],
 ['\\tau_D', 'derivative time \u2014 how far ahead the controller extrapolates'],
 ['\\lambda', 'desired closed-loop time constant; larger is slower and more robust'] ] },
'C-04': { f: 'The closed loop has two distinct jobs and two distinct transfer functions: following a new set point (servo) and rejecting a disturbance (regulator). Both share the same 1 + G_cG_p denominator, which is why one tuning affects both, and why proportional-only control always leaves an offset \u2014 the loop needs a standing error to produce an output. Integral action is what removes that offset, at the cost of stability margin.', s: [
 ['Y', 'controlled variable \u2014 what you measure'], ['Y_{sp}', 'set point \u2014 what you asked for'],
 ['D', 'disturbance entering the process'],
 ['G_c', 'controller transfer function'], ['G_p', 'process transfer function'],
 ['G_d', 'disturbance transfer function'],
 ['e_{ss}', 'steady-state offset left after the response settles'],
 ['K_c,\\ K_p', 'controller gain and process gain'],
 ['IAE', 'integral of absolute error \u2014 one number summarising how bad the whole response was'] ] },
'C-05': { f: 'The Bode plot asks one question at every frequency: how much does the loop amplify, and how far behind is it? Instability is the case where the loop returns a signal amplified and exactly inverted \u2014 gain 1 at \u2212180\u00b0. Gain margin is how much more gain you could add before that happens; phase margin is how much more lag. Dead time adds phase without touching gain, which is why it eats margin so efficiently.', s: [
 ['G_{OL}', 'open-loop transfer function \u2014 controller and process in series'],
 ['\\omega', 'frequency, rad/time'], ['i', 'the imaginary unit'],
 ['AR', 'amplitude ratio \u2014 the loop gain at that frequency'],
 ['\\phi', 'phase lag, degrees'],
 ['GM', 'gain margin \u2014 the factor by which gain can rise before instability; target 2 or more'],
 ['PM', 'phase margin \u2014 the extra lag tolerable before instability; target 30\u201345\u00b0'],
 ['K_c,\\ \\tau_I,\\ \\tau_D', 'PID settings being tested'],
 ['K_p,\\ \\tau,\\ \\theta', 'process gain, time constant and dead time'] ] },
'C-06': { f: 'The Nyquist plot is the same information as Bode drawn as one curve in the complex plane, and it makes the stability question geometric: does the curve encircle the point \u22121? The closest approach to that point is the maximum sensitivity M_s, which is a better single robustness number than either margin \u2014 it bounds both at once. Direct substitution finds the ultimate gain and frequency exactly, without reading anything off a graph.', s: [
 ['G_{OL}', 'open-loop transfer function evaluated at s = i\u03c9'],
 ['\\omega', 'frequency, rad/time'], ['\\omega_u', 'ultimate frequency \u2014 where the phase reaches \u2212180\u00b0'],
 ['M_s', 'maximum sensitivity \u2014 the inverse of the closest approach to \u22121; below 2 is comfortable'],
 ['GM,\\ PM', 'gain and phase margin read off the same curve'],
 ['G_c,\\ G_p', 'controller and process transfer functions'] ] },
'C-07': { f: 'Cascade puts a fast secondary loop inside a slow primary one. The inner loop catches a disturbance while it is still in the utility \u2014 a change in steam pressure, say \u2014 and corrects it before the primary variable has even noticed. For this to work the inner loop must be several times faster than the outer; if the two time constants are close, cascade adds complexity and buys nothing.', s: [
 ['G_{c1},\\ G_{c2}', 'primary (outer, usually PI) and secondary (inner, usually P-only) controller'],
 ['G_{p1},\\ G_{p2}', 'primary and secondary process transfer functions'],
 ['G_{inner}', 'closed-loop transfer function of the whole inner loop, as the outer loop sees it'],
 ['K_{c2}', 'inner controller gain'],
 ['Y_1', 'primary controlled variable \u2014 the one you actually care about'],
 ['D_2', 'disturbance entering the secondary loop \u2014 what cascade is for'],
 ['G_{d2}', 'transfer function from that disturbance to the output'],
 ['\\tau_1,\\ \\tau_2', 'primary and secondary time constants; \u03c4\u2081/\u03c4\u2082 of 5 or more makes cascade worthwhile'] ] },
'C-08': { f: 'Feedforward acts on a measured disturbance before it reaches the controlled variable, so in principle it can cancel it perfectly. In practice the compensator is a ratio of two transfer functions and is only realisable if the disturbance path is slower than the manipulated path; if it is not, you get the static gain and accept an imperfect cancel. Feedback is kept in parallel to clean up the model error the feedforward leaves behind.', s: [
 ['G_f', 'feedforward compensator \u2014 what the disturbance measurement is multiplied by'],
 ['G_d', 'transfer function from disturbance to output'],
 ['G_p', 'transfer function from manipulated variable to output'],
 ['K_f', 'feedforward static gain, \u2212K_d/K_p'],
 ['K_d,\\ K_p', 'disturbance and process gain'],
 ['\\tau_{ld},\\ \\tau_{lg}', 'lead and lag time constants of the compensator'],
 ['\\theta_d,\\ \\theta_p', 'dead time in the disturbance and process paths'],
 ['\\theta_f', 'dead time the compensator must impose, \u03b8_d \u2212 \u03b8_p; negative means it cannot be realised'] ] },
'C-09': { f: 'A level in a tank integrates \u2014 there is no self-regulation, so any flow imbalance runs the level to a wall eventually. That single integrator is why level loops behave unlike everything else: they cannot offset, they are easy to make unstable with integral action, and in surge service you actually want them loose, letting the level swing so the downstream flow stays smooth.', s: [
 ['A', 'tank cross-sectional area, m\u00b2'], ['h', 'liquid level, m'], ['h_{max}', 'high-level trip, m'],
 ['q_{in},\\ q_{out}', 'inlet and outlet volumetric flow, m\u00b3/s'],
 ['G_p(s)', 'process transfer function \u2014 a pure integrator, 1/As'],
 ['K_c', 'controller gain; P-only averaging control uses a deliberately low value'],
 ['\\tau_r', 'time for the level to reach a limit at the current imbalance, s'] ] },
'C-10': { f: 'Identification runs the whole tuning chain backwards. Step the valve, record the curve, and the final change over the step size gives K_p. Two time points on the rising curve are then enough to solve for \u03c4 and \u03b8 simultaneously \u2014 Sundaresan\u2013Krishnaswamy uses 35.3 % and 85.3 %, Smith uses 28.3 % and 63.2 %. Both beat drawing a tangent by hand, which is notoriously sensitive to noise.', s: [
 ['K_p', 'process gain \u2014 \u0394y\u221e divided by the size of the input step'],
 ['\\Delta y_{\\infty}', 'total change in the output once it settles'],
 ['\\tau', 'process time constant'], ['\\theta', 'process dead time'],
 ['t_{28.3},\\ t_{63.2}', 'times to reach 28.3 % and 63.2 % of the final change (Smith method)'],
 ['t_{35.3},\\ t_{85.3}', 'times to reach 35.3 % and 85.3 % (Sundaresan\u2013Krishnaswamy)'] ] },
'C-11': { f: 'A Smith predictor hides the dead time from the controller: an internal model predicts what the process will eventually do, the controller is tuned against that undelayed prediction, and only the difference between model and measurement is fed back. When the model is right the loop behaves as if \u03b8 were zero. When the model is wrong \u2014 and dead time is the parameter that drifts most \u2014 the compensation degrades quickly, which is why plants keep an IMC-PI fallback.', s: [
 ['G_c', 'controller, tuned as if there were no dead time'],
 ['G', 'process model without the delay'],
 ['e^{-\\theta s}', 'the dead-time element being compensated'],
 ['\\theta', 'dead time, time units'],
 ['Y', 'measured output'], ['Y_{sp}', 'set point'] ] }
});

Object.assign(NOM, {
'Q-01': { f: 'All three models compute the same thing \u2014 the excess Gibbs energy of mixing \u2014 and differ only in what physics they put into it. Wilson uses volume-weighted local compositions and cannot describe two liquid phases at all; NRTL adds a non-randomness parameter and can; UNIQUAC separates the size-and-shape contribution from the energetic one, which is why it extrapolates best. Differentiate G\u1d31 with respect to mole number and you get \u03b3, and \u03b3 is what every VLE calculation downstream needs.', s: [
 ['\\gamma_1,\\ \\gamma_2', 'activity coefficient of each component \u2014 how far it departs from ideal solution'],
 ['x_1,\\ x_2', 'liquid mole fractions'],
 ['G^E', 'excess Gibbs energy of mixing, J/mol \u2014 what every model actually correlates'],
 ['\\Lambda_{12},\\ \\Lambda_{21}', 'Wilson binary interaction parameters'],
 ['\\tau_{12},\\ \\tau_{21}', 'NRTL dimensionless interaction energies'],
 ['G_{12},\\ G_{21}', 'NRTL non-randomness factors, exp(\u2212\u03b1\u03c4)'],
 ['R', 'gas constant, 8.314 J/mol\u00b7K'], ['T', 'absolute temperature, K'] ] },
'Q-02': { f: 'The modified Raoult law is the whole calculation: partial pressure equals mole fraction times activity coefficient times pure vapour pressure. NRTL supplies the \u03b3s, Antoine supplies the P\u02e2\u1d43\u1d57s, and summing the partial pressures to the system pressure fixes the bubble temperature. An azeotrope is simply the composition where \u03b3\u2081P\u2081\u02e2\u1d43\u1d57 = \u03b3\u2082P\u2082\u02e2\u1d43\u1d57 \u2014 the relative volatility passes through 1 and no column can cross it.', s: [
 ['y_i,\\ x_i', 'mole fraction of component i in the vapour and in the liquid'],
 ['\\gamma_i', 'liquid-phase activity coefficient of i from NRTL'],
 ['P_i^{sat}', 'pure-component vapour pressure at T, bar'], ['P', 'total system pressure, bar'],
 ['\\tau_{ij}', 'NRTL interaction parameter, \u0394g_ij/RT'],
 ['\\Delta g_{ij}', 'interaction energy between an i\u2013j pair, J/mol'],
 ['G_{ij}', 'NRTL non-randomness factor'],
 ['\\alpha', 'NRTL non-randomness constant, usually 0.2\u20130.47'],
 ['\\alpha_{12}', 'relative volatility; passing through 1 marks the azeotrope'],
 ['R', 'gas constant'], ['T', 'temperature, K'] ] },
'Q-03': { f: 'UNIQUAC splits the activity coefficient in two. The combinatorial part depends only on molecular size and shape \u2014 r and q come from group volumes and surfaces, no fitting \u2014 and it captures the entropy of mixing a small molecule with a big one. The residual part carries the energetics in two adjustable parameters. Because the geometry is fixed independently, the two fitted numbers do less work and extrapolate further than in a purely empirical model.', s: [
 ['\\gamma_i', 'activity coefficient \u2014 the product of a combinatorial and a residual part'],
 ['\\Phi_i', 'volume fraction of component i'],
 ['\\theta_i', 'surface area fraction of component i'],
 ['r_i,\\ q_i', 'van der Waals volume and surface-area parameters of component i, from group tables'],
 ['z', 'coordination number, fixed at 10'],
 ['l_i', 'a combinatorial grouping term built from r, q and z'],
 ['x_i,\\ x_j', 'liquid mole fractions'],
 ['\\tau_{ij}', 'residual interaction parameter, exp(\u2212\u0394u_ij/RT)'],
 ['\\Delta u_{ij}', 'interaction energy, J/mol \u2014 the fitted quantity'],
 ['T', 'temperature, K'] ] },
'Q-04': { f: 'All four cubics are the same equation with different attraction terms. Van der Waals gets the shape right and the numbers wrong; Redlich\u2013Kwong fixes the temperature dependence; SRK and Peng\u2013Robinson make the attraction depend on the acentric factor so the vapour pressure comes out right, and PR additionally fixes liquid density. Written in Z-form they become a cubic whose three roots are the vapour, the liquid and a meaningless middle one.', s: [
 ['P', 'pressure, bar'], ['T', 'temperature, K'], ['V', 'molar volume, m\u00b3/mol'],
 ['R', 'gas constant'],
 ['a', 'attraction parameter \u2014 the pull between molecules'],
 ['b', 'co-volume \u2014 the space molecules themselves occupy'],
 ['\\alpha(T)', 'temperature function on the attraction term; where SRK and PR differ from RK'],
 ['u,\\ w', 'the two constants that specialise the generic cubic into vdW, RK, SRK or PR'],
 ['Z', 'compressibility factor, PV/RT \u2014 1 for an ideal gas'],
 ['A,\\ B', 'dimensionless groups aP/R\u00b2T\u00b2 and bP/RT'],
 ['m', 'the acentric-factor polynomial inside \u03b1(T)'],
 ['T_r', 'reduced temperature, T/T_c'], ['\\omega', 'acentric factor'] ] },
'Q-05': { f: 'An equation of state gives you Z; departure functions turn Z into everything else. Integrating (Z \u2212 1)/P gives the fugacity coefficient, which is what phase equilibrium actually equates; integrating the temperature derivative gives the enthalpy and entropy departures, which is how a real-gas compressor or throttle is calculated. The ideal-gas property plus the departure is the real property \u2014 that is the whole architecture of applied thermodynamics.', s: [
 ['\\phi', 'fugacity coefficient, f/P \u2014 the correction that makes a real gas behave like an ideal one'],
 ['f', 'fugacity, bar \u2014 the effective pressure that drives phase equilibrium'],
 ['Z', 'compressibility factor'], ['P', 'pressure, bar'],
 ['A,\\ B', 'the dimensionless EOS groups'],
 ['H - H^{ig}', 'enthalpy departure \u2014 real minus ideal-gas enthalpy, J/mol'],
 ['S - S^{ig}', 'entropy departure, J/mol\u00b7K'],
 ['\\mu', 'chemical potential, J/mol'], ['R,\\ T', 'gas constant and temperature'] ] },
'Q-06': { f: 'Two liquids split when mixing them costs Gibbs energy rather than saving it \u2014 that is, when the \u0394G_mix curve develops two minima with a hump between. The common tangent to those minima gives the compositions of the two phases in equilibrium, and the width between them is the miscibility gap. The distribution coefficient that extraction modules use is nothing more than the ratio of those two tie-line ends.', s: [
 ['\\Delta G_{mix}', 'Gibbs energy of mixing, J/mol \u2014 a hump means the mixture would rather split'],
 ['x_1,\\ x_2', 'mole fractions in a phase'],
 ['\\gamma_1,\\ \\gamma_2', 'activity coefficients from the chosen model'],
 ['\\alpha,\\ \\beta', 'the two liquid phases in equilibrium'],
 ['K_D', 'distribution coefficient \u2014 solute concentration ratio between the phases'],
 ['R,\\ T', 'gas constant and temperature'] ] },
'Q-07': { f: 'Vapour pressure is the single most important property in separation, and Antoine is the working correlation \u2014 three constants, valid over a stated window, and dangerous outside it. Clausius\u2013Clapeyron is the physics underneath: ln P\u02e2\u1d43\u1d57 against 1/T is straight because the slope is the heat of vaporisation. Watson\u2019s correlation then carries \u0394H_vap from the boiling point to any other temperature.', s: [
 ['P^{sat}', 'saturation (vapour) pressure, bar or mmHg depending on the constant set'],
 ['A,\\ B,\\ C', 'Antoine constants \u2014 always quote them with their units and their valid range'],
 ['T', 'temperature'],
 ['\\Delta H_{vap}', 'enthalpy of vaporisation, J/mol \u2014 the slope of the Clausius\u2013Clapeyron line'],
 ['H_{vap,b}', 'heat of vaporisation at the normal boiling point'],
 ['T_r,\\ T_{rb}', 'reduced temperature and reduced normal boiling point'],
 ['R', 'gas constant'] ] },
'Q-08': { f: 'The Gibbs\u2013Duhem equation says the two activity coefficients in a binary are not independent, so a data set that violates it is wrong no matter how smooth it looks. The area test integrates ln(\u03b3\u2081/\u03b3\u2082) across the composition range and demands it come to zero; the point test looks at the residuals in y one composition at a time and demands they scatter rather than trend. Passing both is the entry ticket for regressing a model.', s: [
 ['\\gamma_1,\\ \\gamma_2', 'the two activity coefficients'],
 ['x_i', 'liquid mole fraction'], ['y_i', 'vapour mole fraction'],
 ['D', 'area-test deviation, % \u2014 the Herington criterion; below 10 % is the usual pass'],
 ['A', 'the Herington temperature-correction term'],
 ['J', 'temperature-range term in the Herington test'],
 ['\\Delta y', 'point-test residual, y measured minus y calculated'],
 ['T_{max},\\ T_{min}', 'the temperature extremes of the data set'],
 ['P', 'system pressure'] ] },
'M-01': { f: 'Plate-to-plate is distillation without shortcuts: alternate the equilibrium relation and the mass balance one stage at a time from the top down. The Sorel form carries a full energy balance, so the vapour and liquid flows change from tray to tray; the Lewis simplification assumes they do not, which is what makes McCabe\u2013Thiele a straight line. The two agree when the molar latent heats match, and diverge exactly as much as those latent heats differ.', s: [
 ['V_n,\\ L_n', 'vapour and liquid molar flow leaving stage n'],
 ['y_{n+1},\\ x_n', 'vapour rising from stage n+1 and liquid falling from stage n'],
 ['D', 'distillate molar flow'], ['x_D', 'distillate composition, mole fraction of the light key'],
 ['H_{n+1},\\ h_n', 'vapour and liquid molar enthalpy on the stage, J/mol'],
 ['h_D', 'distillate enthalpy, J/mol'], ['Q_C', 'condenser duty, W'],
 ['\\lambda_n', 'molar latent heat of the mixture on stage n \u2014 constant molar overflow assumes it is the same everywhere'] ] },
'M-02': { f: 'Lewis\u2013Matheson is the multicomponent version of plate-to-plate: guess the distributions of the non-key components, run the rectifying section down from the top and the stripping section up from the bottom, and see whether the two profiles meet at the feed. They will not on the first try, so the guesses are corrected and the sweep repeated. It converges reliably for narrow-boiling mixtures and struggles when a component is nearly non-distributed.', s: [
 ['y_{i,n+1},\\ x_{i,n}', 'vapour and liquid mole fraction of component i on the stages either side of n'],
 ['L,\\ V', 'liquid and vapour molar flow in the section'],
 ['D,\\ B', 'distillate and bottoms molar flow'],
 ['x_{i,D},\\ x_{i,B}', 'component i in the distillate and the bottoms'],
 ['\\alpha_i', 'relative volatility of i against the reference component'],
 ['x_{LK},\\ x_{HK}', 'light-key and heavy-key mole fractions \u2014 the two components whose split you specify'] ] },
'M-03': { f: 'The \u03b8-method fixes the recurring problem of plate-to-plate: the component balances come out inconsistent with the overall balance. Instead of re-guessing, it multiplies every calculated d_i/b_i ratio by a single number \u03b8 chosen so the corrected distillate flows add up to D exactly. One scalar equation, one Newton solve, and the whole distribution is forced consistent \u2014 which is why the method converges where naive iteration oscillates.', s: [
 ['d_i,\\ b_i', 'molar flow of component i in the distillate and in the bottoms'],
 ['\\theta', 'the correction multiplier applied to every d_i/b_i ratio'],
 ['z_i', 'mole fraction of component i in the feed'],
 ['D,\\ B', 'total distillate and bottoms flow'],
 ['\\alpha_i', 'relative volatility of component i'],
 ['x_{i,D},\\ x_{i,B}', 'corrected product compositions'] ] },
'M-04': { f: 'The bubble-point method solves the column as a matrix rather than a march. Writing the component balance for every stage gives a tridiagonal system in the liquid mole fractions \u2014 one per component \u2014 which the Thomas algorithm solves in a single pass. Normalising and running a bubble-point calculation on each stage updates the temperature profile, the energy balances update the flows, and the cycle repeats. This is what commercial simulators actually run.', s: [
 ['A_j,\\ B_j,\\ C_j,\\ D_j', 'the sub-diagonal, diagonal, super-diagonal and right-hand-side coefficients for stage j'],
 ['x_{i,j}', 'liquid mole fraction of component i on stage j \u2014 the unknowns being solved for'],
 ['V_j,\\ L_j', 'vapour and liquid flow leaving stage j'],
 ['K_{i,j}', 'K-value of component i on stage j, y/x'],
 ['K_{ref}', 'K-value of the reference component, from which the others follow through \u03b1'],
 ['F_m,\\ W_m', 'feed and side-draw on stage m'],
 ['\\Delta H_v', 'molar latent heat used in the energy balance, J/mol'],
 ['T_b', 'bubble-point temperature of the stage, K'] ] },
'M-05': { f: 'Once the two key components are specified, everything else in the feed is already decided. Hengstebeck\u2013Geddes says the log of the split ratio of any component is linear in the log of its relative volatility, and the two keys fix that straight line. Non-keys lighter than the light key go almost entirely overhead, heavier ones almost entirely to the bottoms, and the ones in between distribute \u2014 which is exactly the set you have to watch.', s: [
 ['d_i,\\ b_i', 'component i in the distillate and the bottoms, mol/s'],
 ['\\alpha_i', 'relative volatility of component i against the heavy key'],
 ['A,\\ C', 'intercept and slope of the Hengstebeck\u2013Geddes line, fixed by the two keys'],
 ['N_{min}', 'minimum stages at total reflux \u2014 C equals N_min when the correlation is exact'],
 ['d_{LK},\\ b_{LK}', 'light key in the distillate and bottoms'],
 ['d_{HK},\\ b_{HK}', 'heavy key in the distillate and bottoms'],
 ['\\alpha_{LK,HK}', 'relative volatility between the two keys \u2014 the difficulty of the separation'],
 ['z_i', 'feed mole fraction of component i'], ['F', 'feed molar flow'] ] },
'M-06': { f: 'Underwood answers the multicomponent minimum-reflux question in two steps. The first equation is solved for the root \u03b8 lying between the volatilities of the two keys \u2014 that root encodes the feed condition and the pinch. Substituting it into the second equation gives R_min directly. The real reflux is then a multiple of it, typically 1.1\u20131.3, and the Gilliland correlation converts that ratio into an actual stage count.', s: [
 ['\\alpha_i', 'relative volatility of component i against the heavy key'],
 ['z_i', 'feed mole fraction of component i'],
 ['\\theta', 'the Underwood root lying between \u03b1_LK and \u03b1_HK'],
 ['q', 'feed thermal condition \u2014 1 for saturated liquid, 0 for saturated vapour'],
 ['R_{min}', 'minimum reflux ratio \u2014 infinite stages would be needed at this value'],
 ['x_{i,D}', 'distillate composition of component i'],
 ['N_{min}', 'minimum stages at total reflux (Fenske)'],
 ['N', 'actual stages at the operating reflux (Gilliland)'],
 ['N_R,\\ N_S', 'stages above and below the feed (Kirkbride)'],
 ['z_{LK},\\ z_{HK}', 'light- and heavy-key mole fractions in the feed'] ] },
'X-01': { f: 'The Hatta number asks where the reaction happens. If the gas dissolves and reacts slowly, it fills the bulk liquid and the reaction is a bulk phenomenon \u2014 Ha below 0.3. If it reacts as fast as it diffuses, the whole reaction is confined to the thin film at the interface and the liquid volume is irrelevant \u2014 Ha above 3. Between those the film both reacts and delivers, and the enhancement factor E measures how much faster absorption is than pure physical absorption.', s: [
 ['Ha', 'Hatta number \u2014 reaction rate in the film compared with diffusion through it'],
 ['k_2', 'second-order rate constant, m\u00b3/mol\u00b7s'],
 ['C_{B,L}', 'concentration of the liquid-phase reactant B in the bulk, mol/m\u00b3'],
 ['C_{A,i}', 'concentration of the dissolved gas A at the interface, mol/m\u00b3'],
 ['D_A,\\ D_B', 'diffusivity of A and B in the liquid, m\u00b2/s'],
 ['k_L', 'liquid-side mass-transfer coefficient, m/s'],
 ['E', 'enhancement factor \u2014 absorption with reaction divided by absorption without'],
 ['E_i', 'instantaneous enhancement factor \u2014 the ceiling E can never exceed'],
 ['b', 'stoichiometric moles of B consumed per mole of A'] ] },
'X-02': { f: 'This is the Hatta argument drawn rather than calculated. The concentration profile through the liquid film tells you the regime at a glance: a straight line reaching the bulk means slow reaction, a curve that hits zero inside the film means fast reaction and a reaction plane, and a profile that never leaves the first micron means instantaneous reaction. Where the profile dies is where your reactor volume is doing work.', s: [
 ['C_A', 'dissolved gas concentration at depth z, mol/m\u00b3'],
 ['C_{A,i}', 'its value at the gas\u2013liquid interface'],
 ['C_{A,L}', 'its value in the bulk liquid \u2014 zero in the fast-reaction regime'],
 ['C_B,\\ C_{B,L}', 'liquid reactant concentration in the film and in the bulk'],
 ['z', 'distance into the liquid film, m'],
 ['\\delta', 'film thickness, m \u2014 D_A/k_L'],
 ['D_A,\\ D_B', 'diffusivities in the liquid'],
 ['k_2', 'second-order rate constant'], ['Ha', 'Hatta number'],
 ['b', 'stoichiometric coefficient'] ] },
'X-03': { f: 'Four Damk\u00f6hler numbers, one question each, all built the same way: reaction rate divided by a competing transport rate. Da_I compares reaction with bulk flow and tells you the conversion; Da_II compares it with external mass transfer; Da_III with pore diffusion inside the pellet; Da_IV with heat removal. Whichever is largest is the phenomenon controlling your reactor, and the one you should be modelling carefully.', s: [
 ['Da_I', 'reaction rate against convective flow \u2014 essentially k\u03c4; sets conversion'],
 ['Da_{II}', 'reaction rate against external mass transfer to the particle'],
 ['Da_{III}', 'reaction rate against diffusion inside the pellet \u2014 the Thiele modulus squared'],
 ['Da_{IV}', 'heat generation against heat removal \u2014 the runaway indicator'],
 ['k', 'rate constant'], ['C_0', 'inlet concentration, mol/m\u00b3'], ['n', 'reaction order'],
 ['\\tau', 'residence time, s'],
 ['k_c', 'external mass-transfer coefficient, m/s'], ['a_v', 'interfacial area per unit volume, m\u207b\u00b9'],
 ['\\phi', 'Thiele modulus'], ['L', 'characteristic pellet dimension, m'],
 ['D_e', 'effective diffusivity, m\u00b2/s'],
 ['\\Delta H_r', 'heat of reaction, J/mol'], ['h', 'heat-transfer coefficient, W/m\u00b2\u00b7K'],
 ['T_0', 'reference temperature, K'] ] },
'X-04': { f: 'A slurry reactor stacks four resistances in series between the gas bubble and the active site: through the bubble film, across the gas\u2013liquid interface, through the film round the catalyst particle, and into the pores. They add as reciprocals, so the largest one dominates and the others are noise. Plotting them as a bar chart is the fastest diagnosis in reaction engineering \u2014 it tells you immediately whether to stir harder, add catalyst, or make the particles smaller.', s: [
 ['r_{obs}', 'observed rate, mol/m\u00b3\u00b7s'],
 ['k_g a_b', 'gas-side coefficient times bubble area \u2014 usually negligible'],
 ['k_L a_b', 'liquid-side coefficient times bubble area, s\u207b\u00b9 \u2014 usually the big one'],
 ['H', 'Henry constant \u2014 the solubility of the gas'],
 ['k_c a_p', 'particle film coefficient times external particle area, s\u207b\u00b9'],
 ['\\eta', 'pellet effectiveness factor'], ['k_v', 'intrinsic volumetric rate constant, s\u207b\u00b9'],
 ['m', 'catalyst loading, kg/m\u00b3'], ['\\rho_p', 'particle density, kg/m\u00b3'],
 ['d_p', 'particle diameter, m'], ['\\phi', 'Thiele modulus'] ] },
'X-05': { f: 'Trickle beds have a problem no other reactor has: the liquid may not cover the catalyst. The wetting efficiency f_w depends on liquid mass velocity, and a partially wetted pellet can be faster than a wetted one for a gas-limited reaction and much slower for a liquid-limited one. Overall effectiveness is therefore a weighted sum of a wetted and a dry contribution \u2014 which is why trickle beds are so often run with liquid recycle just to keep the bed wet.', s: [
 ['f_w', 'wetting efficiency \u2014 fraction of external pellet area covered by flowing liquid'],
 ['Re_L', 'liquid Reynolds number based on particle diameter'],
 ['Ga_L', 'liquid Galileo number \u2014 gravity against viscous forces'],
 ['\\eta_{CE}', 'contacting effectiveness \u2014 the overall penalty for imperfect wetting'],
 ['\\eta_{wet},\\ \\eta_{dry}', 'effectiveness of the wetted and the dry fraction of the pellet'],
 ['d_p', 'particle diameter, m'], ['\\rho_L,\\ \\mu_L', 'liquid density and viscosity'],
 ['\\beta_L', 'liquid hold-up \u2014 fraction of bed volume filled with liquid'],
 ['\\varepsilon', 'bed voidage'], ['\\Delta P/L', 'two-phase pressure gradient, Pa/m'], ['g', 'gravitational acceleration'] ] },
'X-06': { f: 'A bubble column has no internals, so everything is set by the gas velocity. It fixes the hold-up, hold-up fixes the interfacial area, and area times the liquid-side coefficient gives k_La \u2014 the single number that decides whether the reactor is mass-transfer or kinetically limited. The trade is that more gas also means more back-mixing in the liquid, so conversion does not rise as fast as k_La suggests.', s: [
 ['\\varepsilon_G', 'gas hold-up \u2014 fraction of the dispersion volume that is bubbles'],
 ['\\varepsilon_L', 'liquid hold-up, 1 \u2212 \u03b5_G'],
 ['Bo', 'Bond number \u2014 gravity against surface tension on the column scale'],
 ['Ga', 'Galileo number \u2014 gravity against viscosity'],
 ['Fr', 'Froude number based on the superficial gas velocity'],
 ['k_L', 'liquid-side mass-transfer coefficient, m/s'],
 ['D_L', 'diffusivity of the gas in the liquid, m\u00b2/s'],
 ['\\nu', 'liquid kinematic viscosity, m\u00b2/s'], ['\\sigma', 'surface tension, N/m'],
 ['d_c', 'column diameter, m'], ['d_b', 'mean bubble diameter, m'],
 ['X', 'conversion'], ['\\tau', 'liquid residence time, s'], ['k', 'reaction rate constant'] ] },
'X-07': { f: 'A non-porous solid reacting with a gas converts from the outside in, leaving an ash shell behind. Three resistances act in series across that geometry \u2014 the gas film, the growing ash layer, and the reaction at the shrinking core \u2014 and each gives a different conversion-against-time curve. Because they are in series their times simply add, and the shape of a measured curve identifies which one controls: linear in X means film, linear in 1 \u2212 (1\u2212X)^(1/3) means reaction.', s: [
 ['X', 'fractional conversion of the solid'],
 ['t', 'time, s'], ['\\tau', 'time for complete conversion of the particle, s'],
 ['\\rho_B', 'molar density of the solid reactant, mol/m\u00b3'],
 ['R', 'initial particle radius, m'],
 ['b', 'moles of solid consumed per mole of gas'],
 ['k_g', 'gas-film mass-transfer coefficient, m/s'],
 ['C_{Ag}', 'bulk gas reactant concentration, mol/m\u00b3'],
 ['D_e', 'effective diffusivity through the ash layer, m\u00b2/s'],
 ['k_s', 'surface reaction rate constant, m/s'],
 ['t_{film},\\ t_{ash},\\ t_{rxn}', 'the time each of the three resistances contributes'] ] },
'X-08': { f: 'The Kunii\u2013Levenspiel model treats a fluidised bed as two worlds: bubbles that carry most of the gas and contain almost no catalyst, and a dense emulsion that is full of catalyst and starved of gas. Reaction happens in the emulsion, so conversion depends on how fast gas can cross from one to the other \u2014 K_bc then K_ce in series. That exchange is the ceiling: beyond a certain point adding catalyst does nothing because the gas never reaches it.', s: [
 ['u_b', 'bubble rise velocity, m/s'], ['u_0', 'superficial gas velocity, m/s'],
 ['u_{mf}', 'minimum fluidisation velocity, m/s'], ['d_b', 'bubble diameter, m'],
 ['K_{bc}', 'bubble-to-cloud exchange coefficient, s\u207b\u00b9'],
 ['K_{ce}', 'cloud-to-emulsion exchange coefficient, s\u207b\u00b9'],
 ['K_f', 'overall bubble-to-emulsion exchange coefficient \u2014 the two in series'],
 ['\\gamma_b,\\ \\gamma_c,\\ \\gamma_e', 'volume of catalyst in the bubble, cloud and emulsion per unit bubble volume'],
 ['\\varepsilon_{mf}', 'voidage at minimum fluidisation'],
 ['D', 'gas diffusivity, m\u00b2/s'], ['k', 'reaction rate constant, s\u207b\u00b9'], ['g', 'gravitational acceleration'] ] }
});

Object.assign(NOM, {
'D-01': { f: 'Every distribution here is the same three objects: a density that says how likely each value is, a cumulative function that is its running integral, and a pair of moments that summarise it. Which distribution you reach for is a modelling decision \u2014 counts of rare events are Poisson, times between them exponential, sums of many small effects normal, products of many small effects lognormal.', s: [
 ['f(x)', 'probability density function \u2014 relative likelihood at x'],
 ['F(x)', 'cumulative distribution function \u2014 probability of being at or below x'],
 ['E[X]', 'expected value, the mean of the distribution'],
 ['V[X]', 'variance \u2014 the mean squared distance from the mean'],
 ['\\sigma', 'standard deviation, \u221aV'], ['\\mu', 'mean'],
 ['\\gamma_1', 'skewness \u2014 zero is symmetric, positive means a long right tail'],
 ['x', 'the random variable\u2019s value'] ] },
'D-02': { f: 'A hypothesis test is a decision rule with a known error rate. You assume the null, work out how surprising your data would be if it were true \u2014 that is the p-value \u2014 and reject when the surprise passes a threshold you fixed in advance. \u03b1 is the risk of rejecting a true null, \u03b2 the risk of missing a real effect, and the only way to lower both at once is more samples.', s: [
 ['H_0', 'null hypothesis \u2014 the default position, usually \u201cno difference\u201d'],
 ['H_1', 'alternative hypothesis \u2014 what you are claiming instead'],
 ['p', 'p-value \u2014 probability of data this extreme if H\u2080 were true'],
 ['t_{obs}', 'the test statistic computed from your sample'],
 ['\\alpha', 'significance level \u2014 accepted probability of a false positive (type I error)'],
 ['\\beta', 'probability of a false negative (type II error); 1 \u2212 \u03b2 is the power'],
 ['n', 'sample size'], ['d', 'effect size you want to be able to detect'],
 ['z_{\\alpha/2}', 'standard-normal critical value for a two-sided test'] ] },
'D-03': { f: 'The central limit theorem is why so much of engineering statistics works at all: whatever the shape of the parent distribution, the mean of a sample of it becomes normal as n grows, with the spread shrinking as 1/\u221an. That is what licenses t-tests and control charts on data that is nothing like normal, and the \u221an is why halving your uncertainty costs four times the samples.', s: [
 ['X_i', 'an individual observation from the parent distribution'],
 ['\\bar X', 'the sample mean'], ['n', 'sample size'],
 ['\\mu', 'mean of the parent distribution'],
 ['\\sigma', 'standard deviation of the parent distribution'],
 ['\\sigma/\\sqrt{n}', 'standard error \u2014 the spread of the sample mean'],
 ['\\gamma_1', 'skewness of the parent; the more skewed, the larger n has to be'],
 ['N(\\mu,\\sigma^2)', 'the normal distribution the sample mean converges to'] ] },
'D-04': { f: 'A confidence interval is the estimate plus a margin, and the margin has three ingredients: how variable the data is, how many samples you took, and how confident you insist on being. Run the same formula backwards and it sizes an experiment \u2014 fix the margin you can live with and it returns n. The t distribution replaces the normal when \u03c3 is estimated rather than known, which matters below about 30 samples.', s: [
 ['\\bar x', 'sample mean'], ['s', 'sample standard deviation'],
 ['n', 'sample size'], ['\\sigma', 'true population standard deviation, when it is known'],
 ['t_{\\alpha/2,n-1}', 'Student-t critical value with n \u2212 1 degrees of freedom'],
 ['z_{\\alpha/2}', 'normal critical value, used when \u03c3 is known'],
 ['\\alpha', 'significance level; 0.05 gives a 95 % interval'],
 ['E', 'margin of error \u2014 the half-width of the interval'],
 ['p', 'sample proportion, for an interval on a fraction'],
 ['\\chi^2', 'chi-squared critical value, used for an interval on the variance'] ] },
'D-05': { f: 'Least squares picks the line that minimises the squared vertical distances, and the two coefficients follow in closed form from the sums of squares. R\u00b2 says how much of the scatter the line explains, but it cannot tell you the line is the right shape \u2014 only the residual plot can. Structure in the residuals means a missing term; a fan shape means the variance is not constant and the fit needs weighting.', s: [
 ['\\beta_0,\\ \\beta_1', 'intercept and slope of the fitted line'],
 ['S_{xx},\\ S_{xy}', 'corrected sums of squares and cross-products of the data'],
 ['x,\\ y', 'the predictor and the response'],
 ['s', 'residual standard deviation \u2014 the typical size of a miss'],
 ['SE', 'standard error of a coefficient'],
 ['R^2', 'fraction of the variance in y explained by the fit'],
 ['R^2_{adj}', 'the same, penalised for the number of parameters'],
 ['n', 'number of data points'],
 ['x_0,\\ y_0', 'a new predictor value and the prediction at it'],
 ['t_{\\alpha/2}', 'critical value for the confidence and prediction bands'] ] },
'D-06': { f: 'Uncertainty propagates through a calculation by first-order Taylor expansion: each input contributes its own uncertainty multiplied by the sensitivity of the result to it, and the contributions add in quadrature. Two consequences follow immediately \u2014 the largest contributor dominates, because squares are unforgiving, and refining anything else is wasted effort until you have dealt with it.', s: [
 ['y', 'the calculated result'], ['x_1,\\ x_2,\\ x_3', 'the measured inputs'],
 ['a,\\ b,\\ c', 'exponents of the inputs in a power-law relationship'],
 ['u_i', 'standard uncertainty of input i, in its own units'],
 ['u_y', 'combined standard uncertainty of the result'],
 ['u_{ij}', 'covariance between inputs i and j, when they are correlated'],
 ['\\partial y/\\partial x_i', 'sensitivity coefficient \u2014 how much y moves per unit of x_i'],
 ['k_c', 'coverage factor; 2 gives roughly 95 % confidence'],
 ['U', 'expanded uncertainty, k_c\u00b7u_y \u2014 the number you actually quote'] ] },
'D-07': { f: 'A control chart separates the noise a process always has from a change that actually happened. The limits are set at three standard errors of the subgroup mean, estimated from the range rather than the standard deviation, so a false alarm happens about once in 370 subgroups. Capability is the separate question of whether that in-control process is good enough for the specification \u2014 C_p asks about spread, C_pk asks about spread and centring together.', s: [
 ['\\bar{\\bar x}', 'grand mean of the subgroup means \u2014 the chart centreline'],
 ['\\bar R', 'mean subgroup range'],
 ['A_2,\\ d_2', 'control-chart constants that convert a range into a standard deviation'],
 ['\\sigma', 'process standard deviation, estimated as R\u0304/d\u2082'],
 ['USL,\\ LSL', 'upper and lower specification limits \u2014 set by the customer, not the process'],
 ['C_p', 'capability \u2014 specification width divided by six sigma; ignores centring'],
 ['C_{pk}', 'capability accounting for how far off centre the process runs'],
 ['ARL_0', 'average run length between false alarms when nothing is wrong'],
 ['ARL_1', 'average subgroups to detect a real shift'],
 ['\\alpha,\\ \\beta', 'false-alarm and missed-detection probabilities'] ] },
'D-08': { f: 'A two-level factorial changes every factor at once on purpose. Each main effect is the average at the high setting minus the average at the low, computed from every run in the design, so the whole experiment is used for every effect \u2014 that is why factorials are so much more efficient than changing one variable at a time. Interactions come out of the same arithmetic, and centre points test whether the response is linear at all.', s: [
 ['\\text{effect}_i', 'main effect of factor i \u2014 the change in response across its two levels'],
 ['\\bar y_{+},\\ \\bar y_{-}', 'mean response at the high and low setting of that factor'],
 ['k', 'number of factors; the design has 2\u1d4f runs'],
 ['n_r', 'replicates of each run'], ['N', 'total number of runs'],
 ['\\sigma', 'run-to-run standard deviation'],
 ['SE', 'standard error of an effect \u2014 what an effect must exceed to be real'],
 ['t_{\\alpha/2}', 'critical value for judging significance'],
 ['\\bar y_{factorial},\\ \\bar y_{centre}', 'mean of the corner runs and of the centre points; a gap means curvature'] ] },
'D-09': { f: 'Arrhenius fitting is linear regression in disguise: plot ln k against 1/T and the slope is \u2212E_a/R, the intercept is ln A. The catch is that the intercept sits at 1/T = 0, far outside any data, so A and E_a are almost perfectly correlated and their individual uncertainties are large even when the line is excellent. Re-centring the fit on a reference temperature inside the data breaks that correlation.', s: [
 ['k', 'rate constant at temperature T'],
 ['A', 'pre-exponential factor \u2014 the intercept, extrapolated to infinite temperature'],
 ['E_a', 'activation energy, J/mol \u2014 from the slope'],
 ['R', 'gas constant, 8.314 J/mol\u00b7K'], ['T', 'absolute temperature, K'],
 ['T_{ref}', 'reference temperature inside the data range'],
 ['k_{ref}', 'rate constant at T_ref \u2014 the re-centred, well-determined parameter'],
 ['\\rho_{AE}', 'correlation between the fitted A and E_a; close to \u22121 in the raw fit'] ] },
'D-10': { f: 'Plant measurements never satisfy the mass balances exactly, so reconciliation adjusts them by the smallest amount that makes the balances close, weighting each adjustment by how much you trust that instrument. What is left over is the residual vector, and its statistic is chi-squared distributed \u2014 too large and the mismatch is not random noise but a gross error: a biased transmitter, a leak, or a stream nobody told you about.', s: [
 ['y', 'vector of raw measurements'], ['\\hat x', 'reconciled values \u2014 the adjusted, balance-consistent estimates'],
 ['A', 'incidence matrix \u2014 the mass balance constraints written as a matrix'],
 ['\\Sigma', 'measurement covariance matrix; its diagonal holds each instrument\u2019s variance'],
 ['r', 'constraint residual \u2014 by how much the raw data fails to balance'],
 ['\\gamma', 'the reconciliation correction applied to the measurements'],
 ['\\chi^2', 'global test statistic; exceeding the critical value signals a gross error'],
 ['m', 'number of constraints'], ['N', 'number of measurements'],
 ['z_i', 'standardised measurement test value for stream i \u2014 the gross-error suspect list'],
 ['V_{ii}', 'variance of the correction to measurement i'] ] },
'S-01': { f: 'Modified Raoult\u2019s law is the base of everything in separations: what leaves in the vapour is what the liquid holds times how volatile it is times how much it dislikes being in solution. The activity coefficient is that last factor \u2014 1 for an ideal mixture, well above 1 for components that repel each other. When \u03b3\u2081P\u2081\u02e2\u1d43\u1d57 equals \u03b3\u2082P\u2082\u02e2\u1d43\u1d57 the relative volatility hits 1 and you have an azeotrope no ordinary column can pass.', s: [
 ['y_i,\\ x_i', 'vapour and liquid mole fraction of component i'],
 ['\\gamma_i', 'liquid activity coefficient \u2014 the departure from ideal solution'],
 ['P_i^{sat}', 'pure-component vapour pressure at the system temperature'],
 ['P', 'total pressure'],
 ['A_{12},\\ A_{21}', 'van Laar or Margules binary constants'],
 ['A,\\ B,\\ C', 'Antoine constants for the vapour-pressure curve'],
 ['T', 'temperature'],
 ['\\alpha_{12}', 'relative volatility \u2014 the separation factor; 1 means no separation'] ] },
'S-02': { f: 'McCabe\u2013Thiele is the mass balance and the equilibrium relation drawn on one square. Operating lines are the mass balances \u2014 straight because constant molar overflow assumes the vapour and liquid flows do not change \u2014 and the equilibrium curve is the thermodynamics. Stepping between them counts stages. Reflux tilts the operating lines: more reflux pushes them towards the diagonal and cuts stages, but every extra unit of reflux is boil-up you pay for forever.', s: [
 ['x,\\ y', 'liquid and vapour mole fraction of the light component'],
 ['x_D', 'distillate composition \u2014 the purity you take overhead'],
 ['x_B', 'bottoms composition \u2014 how much light component you lose downwards'],
 ['z_F', 'feed composition'],
 ['R', 'reflux ratio, L/D \u2014 liquid returned per unit of product taken'],
 ['L,\\ V', 'liquid and vapour molar flows inside the column'],
 ['B', 'bottoms molar flow'],
 ['q', 'feed thermal condition \u2014 1 saturated liquid, 0 saturated vapour; sets the q-line slope'],
 ['N_{min}', 'stages required at total reflux (Fenske) \u2014 the floor no reflux can beat'],
 ['\\alpha', 'relative volatility'] ] },
'S-03': { f: 'Stripping is absorption run backwards: a gas is used to pull a dissolved component out of a liquid. The stripping factor S = mV/L is the whole story \u2014 it is the ratio of the equilibrium line\u2019s capacity to the liquid flow being cleaned. Below 1 the gas saturates before the job is done and no number of stages helps; comfortably above 1 the stage count falls quickly, which is why strippers are run with generous gas rates.', s: [
 ['S', 'stripping factor, mV/L \u2014 above 1 the separation is feasible'],
 ['m', 'slope of the equilibrium line, y* = mx'],
 ['V,\\ L', 'gas and liquid molar flow, mol/s'],
 ['N', 'number of theoretical stages (Kremser)'],
 ['x_{in},\\ x_{out}', 'solute mole fraction in the liquid entering and leaving'],
 ['y_{in}', 'solute mole fraction in the stripping gas entering \u2014 usually near zero'],
 ['x,\\ y', 'liquid and gas compositions on the operating diagram'] ] },
'S-04': { f: 'Absorption is the mirror image of stripping, and the absorption factor A = L/mV plays the same role. Below 1 the solvent runs out of capacity before the gas is cleaned, and the staircase pinches against the equilibrium line no matter how tall you build the column. Design practice is A between 1.2 and 2 \u2014 below that the column is enormous, above it you are paying to regenerate solvent you did not need.', s: [
 ['A', 'absorption factor, L/mV \u2014 solvent capacity against gas load; design 1.2\u20132'],
 ['L,\\ V', 'liquid solvent and gas molar flow, mol/s'],
 ['m', 'slope of the equilibrium line, y* = mx \u2014 essentially the Henry constant over P'],
 ['N', 'number of theoretical stages from the Kremser equation'],
 ['y_{in},\\ y_{out}', 'solute mole fraction in the gas entering and leaving'],
 ['x_{in}', 'solute mole fraction in the lean solvent entering the top'] ] },
'S-05': { f: 'A flash asks how a feed splits when it is dropped to a given temperature and pressure. Writing the component balance and the equilibrium relation together and eliminating x and y leaves one equation in one unknown \u2014 the vapour fraction \u03b2 \u2014 and the Rachford\u2013Rice form of it is monotonic, so a bounded solve always converges. Once \u03b2 is known the phase compositions follow directly.', s: [
 ['z_i', 'mole fraction of component i in the feed'],
 ['K_i', 'K-value of i \u2014 y_i/x_i, the tendency to go to the vapour'],
 ['\\beta', 'vapour fraction \u2014 moles of vapour per mole of feed; the single unknown'],
 ['x_i,\\ y_i', 'liquid and vapour mole fractions after the split'],
 ['P_i^{sat}', 'pure-component vapour pressure at the flash temperature'],
 ['T,\\ P', 'flash temperature and pressure'] ] },
'S-06': { f: 'Extraction replaces a boiling point difference with a solubility difference, so it works where distillation cannot \u2014 heat-sensitive products, close boilers, dilute aqueous streams. The extraction factor E = KS/F does the same job the absorption factor does: below 1 the solvent saturates and the stages pinch. The Kremser form counts the stages, and the staircase on the diagram shows where the pinch sits.', s: [
 ['E', 'extraction factor, KS/F \u2014 solvent capacity against feed load'],
 ['K', 'distribution coefficient \u2014 solute in the extract over solute in the raffinate at equilibrium'],
 ['S', 'solvent flow, kg/h'], ['F', 'feed flow, kg/h'],
 ['N', 'number of theoretical stages'],
 ['x_0,\\ x_N', 'solute concentration in the feed and in the final raffinate'],
 ['y_S', 'solute concentration in the entering solvent \u2014 zero for fresh solvent'],
 ['x,\\ y', 'raffinate and extract compositions on the stage diagram'] ] },
'S-07': { f: 'Fenske\u2013Underwood\u2013Gilliland is the three-step shortcut every preliminary design starts from. Fenske gives the stages at total reflux, Underwood gives the reflux at infinite stages \u2014 the two extremes of the design space. Gilliland interpolates between them with a single empirical curve, so choosing an actual reflux, typically 1.15\u20131.3 times R_min, gives an actual stage count. Kirkbride then places the feed.', s: [
 ['N_{min}', 'minimum stages at total reflux (Fenske)'],
 ['R_{min}', 'minimum reflux at infinite stages (Underwood)'],
 ['N', 'actual stages at the chosen reflux (Gilliland)'],
 ['R', 'operating reflux ratio'],
 ['X,\\ Y', 'the Gilliland correlation coordinates, (R\u2212R_min)/(R+1) and (N\u2212N_min)/(N+1)'],
 ['\\alpha', 'relative volatility between the keys'],
 ['\\alpha_i,\\ z_i', 'relative volatility and feed fraction of each component'],
 ['\\theta', 'the Underwood root between the key volatilities'],
 ['q', 'feed thermal condition'],
 ['x_D,\\ x_B', 'light-key purity in the distillate and bottoms'] ] },
'S-08': { f: 'A packed tower is sized at a fraction of flooding, and flooding is read from the generalised pressure-drop correlation: the flow parameter and the capacity factor locate you on the chart, the packing factor scales it. Design at 70\u201380 % of the flooding gas rate, get the diameter from the resulting velocity, and check that the pressure drop per metre is in the range the packing is meant to work in.', s: [
 ['F_s', 'gas capacity factor, u\u209b\u221a\u03c1_g \u2014 the vertical axis of the correlation'],
 ['F_p', 'packing factor, m\u207b\u00b9'],
 ['u_s', 'superficial gas velocity, m/s'], ['u_{design}', 'design velocity, a fraction of flooding'],
 ['G_f,\\ L_f', 'gas and liquid mass flux, kg/m\u00b2\u00b7s'],
 ['\\rho_g', 'gas density, kg/m\u00b3'],
 ['\\Delta P', 'pressure drop per metre of packing, mbar/m'],
 ['F_{pd}', 'the pressure-drop parameter read from the chart'],
 ['P_{flood}', 'percentage of flooding the design sits at'],
 ['D', 'tower diameter, m'], ['V_g', 'gas volumetric flow, m\u00b3/s'],
 ['C_3,\\ C_4', 'correlation constants'] ] },
'S-09': { f: 'Batch distillation has no steady state: as the light component boils away, the still gets heavier and the distillate gets weaker with every minute. The Rayleigh equation is the integral of that \u2014 a differential mass balance on the pot. Running at constant reflux lets the product purity drift; running at constant purity means raising the reflux continuously and watching the production rate collapse toward the end.', s: [
 ['B_0,\\ B', 'moles in the still at the start and at time t'],
 ['x_0', 'initial still composition'], ['x_B', 'still composition at time t'],
 ['x_D', 'instantaneous distillate composition'],
 ['y', 'vapour composition in equilibrium with the still'],
 ['\\alpha', 'relative volatility'],
 ['R', 'reflux ratio'], ['x_n,\\ y_{n+1}', 'stage compositions in the rectifying section above the pot'] ] },
'S-10': { f: 'A tray only works inside a window. Too little vapour and the liquid weeps or dumps through the holes; too much and it entrains liquid upward or floods the downcomer. Every boundary of that window is a pressure or a velocity computed here \u2014 dry-tray drop plus liquid head gives the total tray drop, the downcomer backup must stay below the tray spacing, and the turndown ratio is simply how wide the window is.', s: [
 ['C_{sb}', 'Souders\u2013Brown capacity parameter at flooding, m/s'],
 ['u_v', 'vapour velocity based on the net area, m/s'],
 ['u_h', 'vapour velocity through the perforations, m/s'],
 ['\\rho_g,\\ \\rho_l', 'vapour and liquid density, kg/m\u00b3'],
 ['\\sigma', 'surface tension, mN/m'],
 ['h_{ow}', 'crest of liquid over the weir, mm'], ['h_w', 'weir height, mm'],
 ['h_d', 'dry-tray pressure drop, mm liquid'],
 ['h_t', 'total tray pressure drop, mm liquid'],
 ['h_{dc}', 'downcomer backup, mm \u2014 must stay under the tray spacing'],
 ['h_{da}', 'head loss under the downcomer apron, mm'],
 ['C_v', 'orifice coefficient for the perforations'],
 ['Q_l', 'liquid volumetric flow, m\u00b3/s'], ['L_w', 'weir length, m'] ] },
'S-11': { f: 'Henry\u2019s law says a sparingly soluble gas dissolves in proportion to its partial pressure, and the constant is the proportionality. The trap is the units: the same physical fact is quoted as pressure over mole fraction, concentration over pressure, or dimensionless, and they differ by factors of thousands. Solubility falls with temperature by a van \u2019t Hoff exponential, which is why hot water strips dissolved gases and cold water absorbs them.', s: [
 ['p_i', 'partial pressure of the gas above the liquid, bar'],
 ['x_i', 'dissolved mole fraction in the liquid'],
 ['c_i', 'dissolved concentration, mol/m\u00b3'],
 ['H_i', 'Henry constant on a pressure-per-mole-fraction basis, bar'],
 ['H^{cp}', 'Henry constant on a concentration-per-pressure basis, mol/m\u00b3\u00b7bar'],
 ['\\Delta_{sol}H', 'enthalpy of dissolution, J/mol \u2014 the temperature dependence'],
 ['R,\\ T', 'gas constant and absolute temperature'],
 ['\\rho_w,\\ M_w', 'density and molar mass of water'], ['M_i', 'molar mass of the gas'],
 ['m', 'equilibrium line slope y* = mx, H_i/P \u2014 the link to the absorber modules'],
 ['L,\\ V', 'liquid and gas molar flow'], ['S', 'stripping factor mV/L'], ['P', 'total pressure'] ] }
});

Object.assign(NOM, {
'F-01': { f: 'Pressure drop in a pipe is one equation \u2014 Darcy\u2013Weisbach \u2014 and everything else is finding the friction factor to put in it. Below Re 2000 the flow is laminar and f is exactly 64/Re, with roughness irrelevant. Above about 4000 it is turbulent and roughness takes over, until at high Reynolds number f stops changing with flow at all: the fully rough regime, where pressure drop is purely quadratic in velocity.', s: [
 ['\\Delta P', 'frictional pressure drop, Pa'], ['L', 'pipe length, m'], ['D', 'internal diameter, m'],
 ['f', 'Darcy friction factor \u2014 four times the Fanning factor; check which one a correlation means'],
 ['\\epsilon', 'absolute wall roughness, mm'], ['\\epsilon/D', 'relative roughness \u2014 the parameter on the Moody chart'],
 ['Re', 'Reynolds number, \u03c1uD/\u03bc \u2014 inertial against viscous forces'],
 ['\\rho', 'fluid density, kg/m\u00b3'], ['u', 'mean velocity, m/s'] ] },
'F-02': { f: 'A pump does not have an operating point; a pump and a pipe do. The pump curve falls with flow, the system curve rises as the square of it, and where they cross is what you get. Everything follows from that intersection: throttling steepens the system curve and slides the point left, trimming the impeller drops the pump curve, and the affinity laws say what a speed change does to both head and flow. NPSH is the separate survival check.', s: [
 ['H', 'pump head, m'], ['H_0', 'shut-off head at zero flow, m'],
 ['a', 'the curvature coefficient of the pump curve, H = H\u2080 \u2212 aQ\u00b2'],
 ['Q', 'volumetric flow, m\u00b3/h'],
 ['H_{sys}', 'head the system demands, m'], ['H_{st}', 'static head \u2014 the lift that exists at zero flow'],
 ['K', 'system resistance coefficient \u2014 the friction term\u2019s multiplier'],
 ['N_1,\\ N_2', 'impeller speeds before and after a change, rpm'],
 ['NPSH_a', 'net positive suction head available, m \u2014 must exceed what the pump requires'],
 ['P_s', 'pressure at the suction vessel, Pa'], ['P_v', 'vapour pressure of the liquid at pumping temperature, Pa'],
 ['z', 'static suction lift or head, m'], ['h_f', 'friction loss in the suction line, m'],
 ['\\rho,\\ g', 'liquid density and gravitational acceleration'] ] },
'F-03': { f: 'A control valve is a variable resistance in series with a fixed one, and that series relationship is what makes valve characteristics matter. The inherent characteristic is what the trim does; the installed characteristic is what you actually get once the pipe takes its share of the pressure. If the valve holds only a small fraction of the total drop, even an equal-percentage trim behaves like quick-opening and the loop gain swings wildly across the range.', s: [
 ['C_v', 'valve flow coefficient \u2014 US gallons per minute of water at 1 psi drop'],
 ['Q', 'volumetric flow through the valve'],
 ['\\Delta P_v', 'pressure drop across the valve, bar'],
 ['G_f', 'specific gravity of the flowing liquid'],
 ['\\ell', 'valve travel, 0 to 1 \u2014 the fraction open'],
 ['f(\\ell)', 'inherent characteristic \u2014 linear, equal-percentage or quick-opening'],
 ['R_v', 'valve rangeability \u2014 the ratio of maximum to minimum controllable flow'],
 ['P_{v,open}/P_{total}', 'valve authority \u2014 the fraction of system pressure drop the valve holds; 0.25\u20130.5 is healthy'] ] },
'F-04': { f: 'An orifice measures flow by converting it into a pressure drop you can read, and the standard turns that reading back into a mass flow. Three corrections do the work: the discharge coefficient for the real jet contraction, the velocity-of-approach factor for the upstream pipe, and the expansibility factor for gases, which compress as they accelerate. The permanent loss \u2014 the price of the measurement \u2014 is most of the differential you measured.', s: [
 ['q_m', 'mass flow rate, kg/s'],
 ['C', 'discharge coefficient \u2014 the Reader-Harris/Gallagher value, about 0.6'],
 ['\\beta', 'diameter ratio d/D \u2014 the single most important design choice, kept between 0.2 and 0.75'],
 ['d', 'orifice bore, m'], ['D', 'upstream pipe internal diameter, m'],
 ['\\Delta P', 'differential pressure across the plate, Pa'],
 ['\\rho', 'fluid density upstream, kg/m\u00b3'],
 ['\\omega', 'expansibility factor \u2014 1 for a liquid, below 1 for a compressible gas'] ] },
'F-05': { f: 'Once a gas is moving fast enough to change its own density, the incompressible pressure-drop equation stops working. The isothermal compressible equation accounts for the gas accelerating as it expands down the line, and it carries a hard limit: at the choke point the exit reaches Mach 1 and no reduction in downstream pressure can increase the flow. Relief and blowdown lines are almost always sized against that limit rather than against friction.', s: [
 ['P_1,\\ P_2', 'upstream and downstream absolute pressure, Pa'],
 ['G', 'mass velocity, kg/m\u00b2\u00b7s \u2014 mass flow divided by pipe area'],
 ['m', 'mass flow rate, kg/s'], ['A', 'pipe cross-sectional area, m\u00b2'],
 ['R_s', 'specific gas constant, R/M_w, J/kg\u00b7K'], ['M_w', 'molar mass, kg/mol'],
 ['T', 'gas temperature, K'], ['f', 'Darcy friction factor'],
 ['L,\\ D', 'pipe length and diameter, m'],
 ['Ma_2', 'Mach number at the outlet; 1 means choked'],
 ['c', 'speed of sound in the gas, m/s'], ['\\gamma', 'ratio of specific heats'],
 ['\\rho_2', 'gas density at the outlet, kg/m\u00b3'] ] },
'F-06': { f: 'Non-Newtonian fluids do not have a viscosity, they have a viscosity that depends on how hard you shear them, so the ordinary Reynolds number is meaningless. The Metzner\u2013Reed number restores it by defining an apparent viscosity at the wall shear rate, and once you have Re_MR the familiar friction-factor machinery works again. Shear-thinning fluids also flatten the velocity profile, which is why a slurry line can be laminar at velocities that would be turbulent for water.', s: [
 ['\\tau', 'shear stress, Pa'], ['\\tau_w', 'shear stress at the pipe wall, Pa'],
 ['\\tau_0', 'yield stress \u2014 the stress below which a Bingham fluid does not move at all, Pa'],
 ['\\dot\\gamma', 'shear rate, s\u207b\u00b9'],
 ['K', 'consistency index of the power-law fluid, Pa\u00b7s\u207f'],
 ['n', 'flow behaviour index \u2014 below 1 shear-thinning, 1 Newtonian, above 1 shear-thickening'],
 ['\\mu_p', 'plastic viscosity of a Bingham fluid, Pa\u00b7s'],
 ['Re_{MR}', 'Metzner\u2013Reed Reynolds number \u2014 the generalised one that keeps the transition near 2100'],
 ['\\rho', 'density, kg/m\u00b3'], ['V', 'mean velocity, m/s'], ['D', 'pipe diameter, m'] ] },
'F-07': { f: 'Fittings are usually charged as an equivalent length of straight pipe, but that is only right at one Reynolds number. The 3K method makes the loss coefficient a function of both Reynolds number and fitting size, which matters because a large valve is proportionally less lossy than a small one. At low flow the viscous term dominates; at high flow K settles to a constant and the fitting behaves like a fixed equivalent length after all.', s: [
 ['K', 'loss coefficient of the fitting \u2014 velocity heads lost'],
 ['K_1', 'the laminar term, divided by Reynolds number'],
 ['K_{\\infty}', 'the fully turbulent asymptote of K'],
 ['K_d', 'the size-dependence term, scaled by pipe diameter'],
 ['Re', 'Reynolds number'], ['D_{in}', 'internal diameter in inches, as the correlation requires'],
 ['L_{eq}', 'equivalent length of straight pipe with the same loss, m'],
 ['L/D', 'equivalent length ratio \u2014 the older, flow-independent way of quoting the same thing'],
 ['\\Delta P', 'pressure loss across the fitting, Pa'],
 ['f', 'pipe friction factor'], ['\\rho,\\ V', 'density and velocity'] ] },
'F-08': { f: 'Compression power is the integral of VdP, and which path you integrate along is the whole design question. Isothermal is the cheapest and unattainable; adiabatic is what a single uncooled stage approaches; polytropic is what real machines do, and it is the basis manufacturers quote because polytropic efficiency does not change with pressure ratio. Interstage cooling exists to bend the path back towards isothermal and keep the discharge temperature survivable.', s: [
 ['H_p', 'polytropic head, J/kg \u2014 the work per unit mass'],
 ['W', 'shaft power, kW'], ['m', 'mass flow, kg/s'],
 ['\\eta_p', 'polytropic efficiency \u2014 typically 0.7\u20130.8 for a centrifugal machine'],
 ['k', 'ratio of specific heats, c_p/c_v'],
 ['n', 'polytropic exponent \u2014 equals k for a perfect adiabatic machine, higher when inefficient'],
 ['r_c', 'compression ratio, P_discharge/P_suction'],
 ['Z', 'compressibility factor of the gas'],
 ['R_s', 'specific gas constant, J/kg\u00b7K'],
 ['T_1,\\ T_2', 'suction and discharge temperature, K'],
 ['N', 'number of stages'] ] },
'F-09': { f: 'Two-phase flow behaves differently depending on how the gas and liquid arrange themselves, so Beggs and Brill first predict the flow pattern from the input liquid fraction and the Froude number, then apply a hold-up correlation belonging to that pattern, then correct it for pipe inclination. Hold-up matters because the liquid moves slower than the gas, so there is more liquid in the pipe than the flow rates suggest \u2014 and that extra liquid is what dominates the pressure gradient in an uphill line.', s: [
 ['\\lambda_L', 'input liquid fraction \u2014 the no-slip liquid volume fraction'],
 ['H_L', 'liquid hold-up \u2014 the actual in-situ liquid fraction; always higher than \u03bb_L'],
 ['v_{sl},\\ v_{sg}', 'superficial liquid and gas velocity, m/s'],
 ['v_m', 'mixture velocity, v_sl + v_sg'],
 ['N_{Fr}', 'Froude number \u2014 selects the flow pattern'],
 ['N_{LV}', 'liquid velocity number, used in the inclination correction'],
 ['\\theta', 'pipe inclination from horizontal, degrees'],
 ['\\psi', 'inclination correction factor applied to the horizontal hold-up'],
 ['a,\\ b,\\ c,\\ C', 'pattern-specific correlation constants'],
 ['\\rho_{ns},\\ \\rho_s', 'no-slip and slip mixture density, kg/m\u00b3'],
 ['\\rho_L,\\ \\rho_g', 'liquid and gas density'], ['\\sigma', 'surface tension, N/m'],
 ['f_{tp}', 'two-phase friction factor'], ['dP/dL', 'total pressure gradient, Pa/m'] ] },
'F-10': { f: 'Pumps in parallel add flow at equal head; pumps in series add head at equal flow. Which one helps depends entirely on the system curve. Against a steep, friction-dominated curve a second parallel pump adds far less than half again the flow \u2014 often only 30 % \u2014 because the extra flow raises the friction that both must fight. Against a flat, static-head-dominated curve parallel operation nearly doubles the flow, and series adds almost nothing.', s: [
 ['H', 'head, m'], ['H_0', 'shut-off head of one pump'],
 ['a', 'pump curve coefficient, H = H\u2080 \u2212 aQ\u00b2'],
 ['Q', 'volumetric flow, m\u00b3/h'],
 ['H_{par},\\ H_{ser}', 'combined curve for n pumps in parallel and in series'],
 ['n', 'number of identical pumps'],
 ['H_{sys}', 'system curve'], ['H_{stat}', 'static head component, m'],
 ['k', 'friction coefficient of the system, giving \u0394H_fric = kQ\u00b2'],
 ['P_{shaft}', 'shaft power, kW'], ['\\eta', 'pump efficiency at the operating flow'],
 ['\\eta_{max}', 'peak efficiency'], ['Q_{bep}', 'flow at the best efficiency point \u2014 stay within 70\u2013120 % of it'],
 ['\\rho,\\ g', 'density and gravitational acceleration'] ] },
'F-11': { f: 'A reciprocating compressor delivers whatever the cylinder sweeps, less what the clearance volume gives back. That is volumetric efficiency, and it collapses as the pressure ratio rises because the gas trapped in the clearance re-expands further before the suction valve can open. Push the ratio high enough and the cylinder does nothing but breathe its own clearance \u2014 which is why reciprocating machines are staged aggressively.', s: [
 ['P_D', 'piston displacement, m\u00b3/s \u2014 the swept volume rate'],
 ['D', 'cylinder bore, m'], ['L', 'stroke, m'], ['N', 'rotational speed, rpm'],
 ['d_{rod}', 'piston rod diameter \u2014 it subtracts from the crank-end swept volume'],
 ['VE', 'volumetric efficiency \u2014 actual intake divided by displacement'],
 ['C', 'clearance volume as a fraction of swept volume, typically 4\u201316 %'],
 ['r', 'stage pressure ratio, P_d/P_s'], ['k', 'ratio of specific heats'],
 ['Z_s,\\ Z_d', 'compressibility at suction and discharge'],
 ['L_v', 'valve loss allowance'],
 ['P_s,\\ P_d', 'suction and discharge pressure'], ['T_s,\\ T_d', 'suction and discharge temperature, K'],
 ['W', 'shaft power, kW'], ['Q_s', 'inlet volumetric flow, m\u00b3/s'],
 ['\\eta_m', 'mechanical efficiency'] ] },
'F-12': { f: 'Long gas pipelines are not sized on velocity, they are sized on the squared-pressure relationship: flow depends on P\u2081\u00b2 \u2212 P\u2082\u00b2 rather than on the difference, because the gas expands and speeds up as the pressure falls. Panhandle and Weymouth are the same equation with different friction assumptions \u2014 Weymouth for shorter, rougher, higher-velocity lines, Panhandle for long transmission where the flow is fully turbulent and smooth.', s: [
 ['Q', 'gas flow at standard conditions, Sm\u00b3/day'],
 ['P_1,\\ P_2', 'inlet and outlet absolute pressure, kPa'],
 ['T_b,\\ P_b', 'base (standard) temperature and pressure the flow is referred to'],
 ['T_f', 'average flowing gas temperature, K'],
 ['G', 'gas specific gravity relative to air'],
 ['L_e', 'equivalent length, corrected for elevation, km'], ['L', 'actual pipeline length, km'],
 ['H_1,\\ H_2', 'inlet and outlet elevation, m \u2014 they matter for dense, high-pressure gas'],
 ['Z', 'average compressibility factor'], ['f', 'friction factor'],
 ['D', 'internal diameter, mm'],
 ['E', 'pipeline efficiency factor \u2014 0.92\u20130.95 for a clean new line'],
 ['s', 'the elevation adjustment exponent'] ] },
'F-13': { f: 'A restriction orifice is deliberately lossy: its job is to burn pressure permanently rather than to measure. Sizing runs the orifice equation backwards from the flow you want to pass. The check that follows is cavitation for liquids \u2014 if the vena contracta drops below the vapour pressure the plate erodes \u2014 and choking for gases, where the flow caps out at the critical pressure ratio. Both are fixed by staging the plates.', s: [
 ['Q', 'volumetric flow, m\u00b3/h'], ['C_d', 'discharge coefficient, about 0.61 for a sharp-edged plate'],
 ['A', 'orifice area, m\u00b2'], ['d,\\ D', 'orifice bore and pipe internal diameter'],
 ['\\beta', 'diameter ratio d/D'], ['\\Delta P', 'pressure drop taken across the plate, bar'],
 ['\\rho', 'fluid density, kg/m\u00b3'],
 ['P_1,\\ P_2', 'upstream and downstream pressure'], ['P_v', 'liquid vapour pressure \u2014 the cavitation floor'],
 ['\\sigma', 'cavitation index \u2014 how much margin there is above vapour pressure'],
 ['m_{crit}', 'critical (choked) mass flow for a gas, kg/s'],
 ['k', 'ratio of specific heats'], ['M', 'molar mass'], ['Z,\\ R,\\ T', 'compressibility, gas constant, temperature'],
 ['n', 'number of plates in a staged installation'],
 ['P_{perm}', 'permanent pressure loss, which for a restriction orifice is the point'] ] },
'F-14': { f: 'A rotameter is a force balance, not a pressure measurement: the float sits where drag plus buoyancy equals its weight, and because the annulus widens as the float rises, the scale is very nearly linear. That balance depends on the density of the fluid, so a meter calibrated on air reads wrong on any other gas \u2014 the correction is the square root of the density ratio, and it is the single most common rotameter error in a plant.', s: [
 ['Q', 'volumetric flow, m\u00b3/h'], ['C_d', 'discharge coefficient of the annulus'],
 ['A_{ann}', 'annular area between the float and the tapered tube at height h, m\u00b2'],
 ['A_f', 'maximum cross-sectional area of the float, m\u00b2'],
 ['V_f', 'float volume, m\u00b3'], ['\\rho_f', 'float material density, kg/m\u00b3'],
 ['\\rho', 'fluid density at flowing conditions, kg/m\u00b3'],
 ['h', 'float height in the tube, mm'],
 ['D_0,\\ D_f', 'tube bore at the bottom and float diameter, mm'],
 ['\\phi', 'tube taper angle'],
 ['Q_{ind}', 'flow the scale indicates'], ['Q_{act}', 'true flow after correction'],
 ['\\rho_{cal},\\ \\rho_{act}', 'density the meter was calibrated on and the actual fluid density'],
 ['g', 'gravitational acceleration'] ] },
'F-15': { f: 'A looped network has more unknowns than you have simple balances, so Hardy Cross solves it iteratively. Guess flows that satisfy continuity at every node, then walk each loop: if the head losses do not sum to zero, apply a correction to every pipe in that loop, sized so the loop closes. Because the correction preserves continuity, you never break what you already satisfied \u2014 and successive sweeps converge on the one flow distribution that satisfies both laws.', s: [
 ['h_f', 'head loss in a pipe, m'],
 ['Q', 'flow in the pipe, m\u00b3/s \u2014 signed by direction round the loop'],
 ['Q_{in},\\ Q_{out}', 'flows entering and leaving a node; their difference must be zero'],
 ['K', 'pipe resistance coefficient in h_f = KQ\u207f'],
 ['n', 'flow exponent \u2014 2 for Darcy\u2013Weisbach, 1.85 for Hazen\u2013Williams'],
 ['\\Delta Q_i', 'the correction applied to every pipe in loop i this iteration'],
 ['f', 'friction factor'], ['L,\\ D', 'pipe length and diameter'],
 ['g', 'gravitational acceleration'] ] }
});

Object.assign(NOM, {
'H-01': { f: 'Q = UA\u0394T_lm is the whole of heat exchanger sizing, and the three factors fail in different ways. The log-mean temperature difference is the correct average driving force for counter-current flow; F corrects it downward for the fact that a multi-pass shell is partly co-current. U is built from resistances in series \u2014 two films, two foulings and a wall \u2014 so the largest one governs, and fouling is usually the one that decides the exchanger\u2019s life.', s: [
 ['Q', 'heat duty, W'], ['A', 'heat transfer area, m\u00b2'],
 ['U_o', 'overall coefficient referred to the outside area, W/m\u00b2\u00b7K'],
 ['\\Delta T_{lm}', 'log-mean temperature difference for pure counter-current flow, K'],
 ['\\Delta T_1,\\ \\Delta T_2', 'the temperature approach at each end of the exchanger, K'],
 ['F', 'LMTD correction factor for multi-pass flow; below 0.75 the configuration is wrong'],
 ['R,\\ P', 'the two dimensionless temperature ratios F is read against'],
 ['h_i,\\ h_o', 'inside and outside film coefficients, W/m\u00b2\u00b7K'],
 ['R_f', 'fouling resistance, m\u00b2\u00b7K/W \u2014 often the largest single term'],
 ['\\lambda_w', 'tube wall thermal conductivity, W/m\u00b7K'],
 ['d_i,\\ d_o', 'tube inside and outside diameter'] ] },
'H-02': { f: 'When you know the inlet temperatures but not the outlets, LMTD needs iteration and \u03b5-NTU does not. Effectiveness is the fraction of the thermodynamically possible heat that the exchanger actually transfers, and it depends on just two groups: NTU, which is size, and C_r, the ratio of the two heat capacity rates. Effectiveness rises steeply with NTU up to about 3 and then saturates \u2014 the reason exchangers above NTU 5 are rare.', s: [
 ['\\varepsilon', 'effectiveness \u2014 actual duty divided by the maximum thermodynamically possible'],
 ['Q', 'actual heat duty, W'], ['Q_{max}', 'duty if the exchanger were infinitely large, W'],
 ['C_{min},\\ C_{max}', 'the smaller and larger of the two mass-flow \u00d7 heat-capacity products, W/K'],
 ['C_r', 'capacity ratio, C_min/C_max \u2014 0 for a condenser or boiler'],
 ['NTU', 'number of transfer units, UA/C_min \u2014 the dimensionless size of the exchanger'],
 ['T_{h,in},\\ T_{c,in}', 'hot and cold inlet temperatures, \u00b0C'],
 ['U,\\ A', 'overall coefficient and area'] ] },
'H-03': { f: 'Heat leaving an insulated pipe crosses three resistances in series: conduction through the insulation, then convection and radiation from the outer surface in parallel. Because the area grows as you add insulation, a thin layer on a small pipe can actually increase the loss \u2014 the critical radius effect. Beyond that the loss falls hyperbolically, so the last 25 mm buys far less than the first, and the economic thickness is where the saving stops paying for the lagging.', s: [
 ['Q/L', 'heat loss per metre of pipe, W/m'],
 ['r_1,\\ r_2', 'pipe outside radius and insulation outside radius, m'],
 ['\\lambda_{ins}', 'insulation thermal conductivity, W/m\u00b7K \u2014 rises with temperature'],
 ['T_i', 'process temperature inside the pipe, \u00b0C'],
 ['T_a', 'ambient air temperature, \u00b0C'], ['T_s', 'outer surface (skin) temperature, \u00b0C \u2014 the personnel-protection check'],
 ['h_c', 'convective coefficient at the outer surface, W/m\u00b2\u00b7K'],
 ['h_r', 'radiative coefficient at the outer surface, W/m\u00b2\u00b7K'],
 ['h_o', 'combined outer coefficient, h_c + h_r'],
 ['\\epsilon', 'surface emissivity \u2014 0.1 for bright metal cladding, 0.9 for painted'],
 ['\\sigma', 'Stefan\u2013Boltzmann constant, 5.67\u00d710\u207b\u2078 W/m\u00b2\u00b7K\u2074'] ] },
'H-04': { f: 'An air cooler has no cooling water and therefore no cold sink below ambient \u2014 the approach to dry-bulb air temperature is what sizes it, and pushing that approach below about 10 K makes the bundle grow without limit. Because air has a poor film coefficient, the tubes are finned and the air side still dominates U. The fan power that pushes the air through is a real and continuing operating cost, and it rises as the cube of air flow.', s: [
 ['m_{air}', 'air mass flow across the bundle, kg/s'],
 ['c_{p,air}', 'air specific heat, ~1.005 kJ/kg\u00b7K'],
 ['\\Delta T_{air}', 'air temperature rise across the bundle, K'],
 ['Q', 'heat duty, W'], ['A', 'bare-tube heat transfer area, m\u00b2'],
 ['U', 'overall coefficient referred to the bare tube, W/m\u00b2\u00b7K'],
 ['\\varepsilon', 'effectiveness'], ['NTU', 'number of transfer units'],
 ['C_r', 'capacity ratio'], ['C_{min}', 'smaller capacity rate, W/K'],
 ['V_{air}', 'air volumetric flow, m\u00b3/s'], ['P_{air}', 'static pressure the fan must develop, Pa'],
 ['W_{fan}', 'fan shaft power, kW'], ['\\eta_{fan}', 'fan and drive efficiency'] ] },
'H-05': { f: 'Batch heating is a first-order approach to a limit, so it is exponential in time: the driving force shrinks as the batch warms and every degree takes longer than the last. With an isothermal medium such as condensing steam the temperature the batch approaches is the steam temperature; with a non-isothermal coolant the medium warms too and the approach is slower. Chasing the last few degrees is what makes batch cycles long.', s: [
 ['t', 'heating or cooling time, s'],
 ['M', 'batch mass in the vessel, kg'], ['c_p', 'batch specific heat, J/kg\u00b7K'],
 ['UA', 'overall coefficient times jacket or coil area, W/K'],
 ['T_0', 'starting batch temperature, \u00b0C'], ['T_1', 'target batch temperature, \u00b0C'],
 ['T', 'medium temperature \u2014 the limit the batch approaches, \u00b0C'],
 ['W', 'mass flow of the heating or cooling medium, kg/s'],
 ['c', 'medium specific heat, J/kg\u00b7K'],
 ['K_1', 'the non-isothermal-medium grouping in the Kern batch equations'],
 ['h_i,\\ h_o', 'inside (agitated) and jacket-side film coefficients, W/m\u00b2\u00b7K'],
 ['\\lambda', 'latent heat of the heating steam, J/kg'],
 ['x', 'wetted fraction of the jacket area'] ] },
'H-06': { f: 'A thermosyphon has no pump: circulation is driven by the density difference between the cold liquid leg going down and the boiling two-phase mixture coming up. Raise the heat flux and more vapour is generated, the riser gets lighter and the driving head rises \u2014 but so does the friction, and eventually friction wins. The circulation ratio settles where the two balance, and a ratio below about 4 risks dryout in the tubes.', s: [
 ['\\Delta P_{drive}', 'driving pressure from the density difference, Pa'],
 ['\\rho_L', 'liquid density in the downcomer, kg/m\u00b3'],
 ['\\rho_{tp}', 'mean two-phase density in the riser, kg/m\u00b3'],
 ['\\rho_g', 'vapour density, kg/m\u00b3'],
 ['z_{liq}', 'static liquid height above the tube inlet, m'], ['L', 'tube length, m'],
 ['x', 'local vapour mass fraction (quality)'], ['x_{out}', 'quality leaving the tubes'],
 ['P_{loss}', 'total frictional and acceleration loss round the circuit, Pa'],
 ['K_{in},\\ K_{out}', 'inlet and outlet loss coefficients'],
 ['\\phi^2', 'two-phase friction multiplier'],
 ['G', 'mass velocity in the tubes, kg/m\u00b2\u00b7s'],
 ['CR', 'circulation ratio \u2014 mass circulated per unit mass vaporised; keep above 4'],
 ['m_{circ},\\ m_{vap}', 'circulating and vaporised mass flow, kg/s'] ] },
'H-07': { f: 'A flat wall is the simplest insulation case: conduction in series with a combined surface coefficient, no area growth and therefore no critical radius. The subtlety is at the surface, where natural convection and radiation act in parallel and both depend on the surface temperature you are solving for \u2014 so the calculation iterates. Emissivity matters more than people expect: bright cladding halves the radiative half of the loss.', s: [
 ['q', 'heat loss per unit area, W/m\u00b2'],
 ['T_{hot}', 'hot face temperature, \u00b0C'], ['T_{amb}', 'ambient temperature, \u00b0C'],
 ['T_s', 'outer surface temperature, \u00b0C \u2014 the touch-safety criterion'],
 ['x', 'insulation thickness, m'], ['k', 'insulation thermal conductivity, W/m\u00b7K'],
 ['h_c', 'natural convection coefficient at the surface, W/m\u00b2\u00b7K'],
 ['h_r', 'radiative coefficient at the surface, W/m\u00b2\u00b7K'],
 ['h_s', 'combined surface coefficient'],
 ['Nu', 'Nusselt number for the natural convection correlation'],
 ['k_a', 'air thermal conductivity'], ['L', 'characteristic length of the surface, m'],
 ['\\varepsilon', 'surface emissivity'], ['\\sigma', 'Stefan\u2013Boltzmann constant'] ] },
'H-08': { f: 'Kern\u2019s shell-side method assumes all the flow crosses the bundle; Bell\u2013Delaware admits it does not. Some leaks through the tube-to-baffle clearance, some past the baffle-to-shell gap, some bypasses round the bundle entirely, and each of those is a correction factor multiplying the ideal coefficient. Multiplying the J factors together typically gives 0.5\u20130.7 \u2014 the honest statement that half the shell-side performance is lost to clearances.', s: [
 ['h_s', 'actual shell-side coefficient, W/m\u00b2\u00b7K'],
 ['h_{id}', 'ideal cross-flow coefficient before any correction'],
 ['J_c', 'correction for the baffle-window flow'],
 ['J_l', 'correction for baffle leakage \u2014 usually the biggest penalty'],
 ['J_b', 'correction for bundle bypass round the outside of the tubes'],
 ['J_s', 'correction for unequal end-baffle spacing'],
 ['J_r', 'correction for adverse temperature gradient at low Reynolds number'],
 ['j_i', 'ideal Colburn j-factor for the tube bank'],
 ['S_m', 'cross-flow area at the shell centreline, m\u00b2'],
 ['m_s', 'shell-side mass flow, kg/s'], ['C_p', 'shell-side fluid specific heat'],
 ['Pr', 'Prandtl number'], ['\\mu,\\ \\mu_w', 'bulk and wall viscosity'],
 ['L_{bc}', 'central baffle spacing, m'],
 ['D_s,\\ D_{otl}', 'shell inside diameter and outer tube limit, m'],
 ['d_o,\\ P_t', 'tube outside diameter and tube pitch'] ] },
'H-09': { f: 'A double-pipe exchanger is one tube inside another, so both sides are simple pipe flow and both coefficients come from the same Dittus\u2013Boelter form \u2014 the only trick is that the annulus needs an equivalent diameter, and the right one differs for heat transfer and for pressure drop. Combine the two films with the wall and the fouling and you have U; the true counter-current arrangement means F is exactly 1, which is why these units are used for small close-approach duties.', s: [
 ['Nu', 'Nusselt number \u2014 the dimensionless film coefficient'],
 ['Re,\\ Pr', 'Reynolds and Prandtl number'],
 ['n', 'the Prandtl exponent \u2014 0.4 when heating the fluid, 0.3 when cooling it'],
 ['D_i', 'inner pipe inside diameter, m'], ['d_o', 'inner pipe outside diameter, m'],
 ['D_h', 'annulus (outer pipe) inside diameter, m'],
 ['D_e', 'annulus equivalent diameter for heat transfer, m'],
 ['h_i,\\ h_o', 'inner-pipe and annulus film coefficients, W/m\u00b2\u00b7K'],
 ['R_{f,i},\\ R_{f,o}', 'fouling resistance on each side, m\u00b2\u00b7K/W'],
 ['k_w', 'wall thermal conductivity'], ['U_o', 'overall coefficient on the outside area'],
 ['L', 'hairpin length, m'], ['Q', 'duty, W'], ['\\Delta T_{lm}', 'log-mean temperature difference'] ] },
'H-10': { f: 'In a jacketed stirred vessel the process-side film coefficient is set by the agitator, not by any flow you specify, so the correlation is written in an impeller Reynolds number. That gives h_i, which combines with the jacket side and the wall into UA \u2014 and UA feeds straight into the batch heating equation. Faster stirring improves h_i only as the two-thirds power, so doubling agitator power buys about 25 % more heat transfer.', s: [
 ['Nu', 'Nusselt number for the vessel wall'],
 ['h_i', 'process-side film coefficient, W/m\u00b2\u00b7K'],
 ['D_T', 'vessel diameter, m'], ['D_a', 'impeller diameter, m'],
 ['k', 'liquid thermal conductivity, W/m\u00b7K'],
 ['Re', 'impeller Reynolds number, \u03c1ND_a\u00b2/\u03bc'],
 ['Pr', 'Prandtl number'], ['\\mu,\\ \\mu_w', 'bulk and wall viscosity \u2014 the viscosity correction matters for viscous batches'],
 ['\\rho', 'liquid density'], ['N', 'agitator speed, rev/s'],
 ['UA', 'overall coefficient times jacket area, W/K'],
 ['M,\\ c_p', 'batch mass and specific heat'],
 ['T_0,\\ T_1', 'initial and target batch temperature'], ['T_{med}', 'jacket medium temperature'],
 ['t', 'batch heating time'] ] },
'H-11': { f: 'Condensate leaving a trap is saturated liquid at the steam pressure; drop it to a lower pressure and part of it must boil, because the liquid is now hotter than its new saturation temperature. The flash fraction is an enthalpy balance and nothing more. Recovering that flash steam into a low-pressure header is one of the cheapest energy savings in a plant \u2014 provided the flash vessel is big enough to disengage the vapour cleanly.', s: [
 ['x', 'flash fraction \u2014 kilograms of vapour per kilogram of condensate'],
 ['h_{f,1}', 'saturated liquid enthalpy at the high pressure, kJ/kg'],
 ['h_{f,2}', 'saturated liquid enthalpy at the flash pressure, kJ/kg'],
 ['h_{fg,2}', 'latent heat at the flash pressure, kJ/kg'],
 ['m_{cond}', 'condensate flow entering the vessel, kg/h'],
 ['m_{flash}', 'flash steam recovered, kg/h'], ['m_{liq}', 'liquid remaining, kg/h'],
 ['V_g', 'vapour volumetric flow, m\u00b3/s'],
 ['u_{max}', 'maximum vapour velocity for droplet disengagement, m/s'],
 ['K', 'Souders\u2013Brown coefficient for the separator'],
 ['\\rho_l,\\ \\rho_g', 'liquid and vapour density'],
 ['D_{vessel}', 'minimum flash-vessel diameter, m'],
 ['Q_{rec}', 'energy recovered in the flash steam, kW'] ] },
'H-12': { f: 'Desuperheating is a mixing enthalpy balance: spray enough water into superheated steam that the mixture lands just above saturation. Too little and the steam stays hot; too much and you carry liquid into the header. The approach temperature is the safety margin \u2014 typically 5\u201310 K above saturation \u2014 and it is what stops a control wobble from producing wet steam.', s: [
 ['m_s', 'superheated steam mass flow entering, kg/h'],
 ['m_w', 'spray water mass flow, kg/h'],
 ['m_2', 'desuperheated steam leaving, m_s + m_w'],
 ['h_s', 'enthalpy of the incoming superheated steam, kJ/kg'],
 ['h_w', 'enthalpy of the spray water, kJ/kg'],
 ['h_2', 'target enthalpy of the outlet steam, kJ/kg'],
 ['T_2', 'outlet steam temperature, \u00b0C'],
 ['T_{sat}', 'saturation temperature at the operating pressure, \u00b0C'],
 ['\\Delta T_{app}', 'approach \u2014 how far above saturation the outlet is held, K'],
 ['P', 'operating pressure, bar'], ['Q', 'heat removed by the spray, kW'] ] }
});

Object.assign(NOM, {
'T-01': { f: 'IF97 does not interpolate a table \u2014 it evaluates a dimensionless Gibbs free energy polynomial for the region you are in, and every property is a derivative of it. Enthalpy, entropy and volume come out of the first derivatives, heat capacities out of the second. That is why the formulation is exactly thermodynamically consistent: the properties cannot disagree with each other because they are all the same function differentiated differently.', s: [
 ['g', 'specific Gibbs free energy \u2014 the master function everything is derived from, kJ/kg'],
 ['\\gamma', 'the dimensionless form of g used in the IF97 polynomials'],
 ['\\pi', 'reduced pressure, p/p*'], ['\\tau', 'inverse reduced temperature, T*/T'],
 ['p', 'pressure, MPa'], ['T', 'temperature, K'],
 ['R', 'specific gas constant of water, 0.461526 kJ/kg\u00b7K'],
 ['h', 'specific enthalpy, kJ/kg'], ['s', 'specific entropy, kJ/kg\u00b7K'],
 ['v', 'specific volume, m\u00b3/kg'],
 ['\\pi_{sat}', 'reduced saturation pressure from the region 4 equation'] ] },
'T-02': { f: 'A psychrometric chart is a plot of two independent properties of moist air, and everything else on it is derived. Humidity ratio comes from the partial pressure of water; enthalpy is the dry air plus the moisture and its latent heat; the saturation curve is the vapour pressure of water against temperature. Cooling along a horizontal line until you hit that curve is the dew point \u2014 which is the whole basis of dehumidification.', s: [
 ['W', 'humidity ratio \u2014 kilograms of water per kilogram of dry air'],
 ['W_s', 'saturation humidity ratio at that temperature'],
 ['p_w', 'partial pressure of water vapour, kPa'],
 ['p', 'total (barometric) pressure, kPa'],
 ['t', 'dry-bulb temperature, \u00b0C'],
 ['h', 'specific enthalpy of the moist air, kJ per kg of dry air'] ] },
'T-03': { f: 'Natural gas is a mixture, so it has no critical point of its own \u2014 pseudocritical constants are estimated from the gas gravity and then used to reduce the pressure and temperature. Dranchuk\u2013Abou-Kassem fits the Standing\u2013Katz chart as an eleven-constant equation in reduced density, solved iteratively. Z is what converts a metering volume into real moles, so an error here propagates straight into custody transfer.', s: [
 ['\\gamma_g', 'gas specific gravity relative to air'],
 ['T_{pc},\\ P_{pc}', 'pseudocritical temperature and pressure of the mixture'],
 ['T_{pr},\\ P_{pr}', 'pseudoreduced temperature and pressure \u2014 T/T_pc and P/P_pc'],
 ['Z', 'compressibility factor \u2014 how far the gas departs from ideal'],
 ['\\rho_r', 'reduced density, the variable the DAK equation is solved for'],
 ['A_1..A_{11}', 'the eleven Dranchuk\u2013Abou-Kassem fitting constants'],
 ['\\epsilon', 'the sour-gas correction to the pseudocriticals (Wichert\u2013Aziz)'] ] },
'T-04': { f: 'Petroleum properties all hang off two numbers: how dense the liquid is and where it boils. API gravity is just a rescaled specific gravity, chosen so that lighter, more valuable crudes get bigger numbers. The Watson K factor combines density with boiling point and characterises how paraffinic the stock is, which in turn predicts viscosity, heat capacity and how it will behave in a cracker.', s: [
 ['API', 'API gravity, 141.5/\u03b3\u2086\u2080 \u2212 131.5 \u2014 higher means lighter'],
 ['\\gamma_{60}', 'specific gravity at 60 \u00b0F relative to water at 60 \u00b0F'],
 ['\\rho_{15}', 'density at 15 \u00b0C, kg/m\u00b3'],
 ['\\alpha_{60}', 'thermal expansion coefficient at 60 \u00b0F, per \u00b0F'],
 ['VCF', 'volume correction factor \u2014 what converts a measured volume to standard temperature'],
 ['K_0,\\ K_1', 'the API-2540 density-dependent expansion constants'],
 ['\\Delta T', 'temperature difference from the standard, \u00b0F'],
 ['K_{UOP}', 'Watson characterisation factor \u2014 ~12.5 paraffinic, ~10 aromatic'],
 ['T_B', 'mean average boiling point, \u00b0R'] ] },
'T-05': { f: 'Most fuel properties do not blend linearly \u2014 mix equal volumes of a thin and a thick oil and you do not get the average viscosity. The fix is a blending index: transform each component into a scale that does blend linearly, average on that scale by volume or weight, then transform back. Viscosity uses the Refutas index, sulphur blends by mass, flash point by its own index, and only density is honestly linear.', s: [
 ['VBI_i', 'viscosity blending index of component i \u2014 the Refutas transform of \u03bd_i'],
 ['\\nu_i', 'kinematic viscosity of component i, cSt'],
 ['\\nu_{mix}', 'blend kinematic viscosity, cSt'],
 ['I_{mix}', 'volume- or weight-averaged blending index'],
 ['w_i', 'weight fraction of component i'], ['v_i', 'volume fraction of component i'],
 ['\\rho_i,\\ \\rho_{mix}', 'component and blend density'],
 ['S_i,\\ S_{mix}', 'component and blend sulphur content, wt %'],
 ['T_{f,i},\\ T_{f,mix}', 'component and blend flash point, \u00b0C'] ] },
'T-06': { f: 'Mixture properties divide into the easy and the hard. Molar mass and heat capacity are honest mole- or mass-weighted averages. Viscosity and thermal conductivity are not \u2014 a light molecule and a heavy one interfere with each other\u2019s momentum transport, so Wilke\u2019s method weights each component by an interaction factor built from the viscosity and molar-mass ratios. Ignore that and a hydrogen-rich mixture comes out badly wrong.', s: [
 ['M_{mix}', 'mixture molar mass, g/mol'], ['M_i,\\ M_j', 'component molar masses'],
 ['y_i,\\ y_j', 'mole fractions'], ['w_i', 'mass fraction of component i'],
 ['c_{p,mix},\\ c_{p,i}', 'mixture and component heat capacity, kJ/kg\u00b7K'],
 ['k_{ratio}', 'ratio of specific heats of the mixture, c_p/c_v'],
 ['\\mu_{mix},\\ \\mu_i', 'mixture and component viscosity, Pa\u00b7s'],
 ['\\phi_{ij}', 'Wilke interaction parameter between components i and j'],
 ['\\lambda_{mix},\\ \\lambda_i', 'mixture and component thermal conductivity, W/m\u00b7K'],
 ['R', 'gas constant'] ] },
'T-07': { f: 'Amine circulation is set by acid-gas loading, not by flow: the difference between the rich and lean loading is how much acid gas each mole of amine can carry, and the required solvent rate follows directly. Everything expensive downstream then scales with that rate \u2014 the reboiler duty is roughly proportional to it, and so is the pump, the exchanger and the regenerator. Pushing the rich loading higher cuts circulation but corrodes the plant.', s: [
 ['n_{acid}', 'moles of acid gas to be removed per hour'],
 ['n_{gas}', 'total gas molar flow'],
 ['y_{CO_2},\\ y_{H_2S}', 'acid-gas mole fractions in and out'],
 ['\\alpha_{rich},\\ \\alpha_{lean}', 'moles of acid gas per mole of amine leaving the absorber and returning from the regenerator'],
 ['L_{amine}', 'amine circulation rate, kmol/h'], ['L_{vol}', 'the same as a volumetric rate, m\u00b3/h'],
 ['Q_{reb}', 'reboiler duty, kW'],
 ['q_{spec}', 'specific reboiler duty, kJ per kg of solvent circulated'],
 ['Q_{cond}', 'regenerator condenser duty, kW'],
 ['Q_{lean/rich}', 'lean/rich exchanger duty, kW'],
 ['c_p', 'solvent heat capacity'], ['\\Delta T_{approach}', 'lean/rich exchanger approach, K'] ] },
'T-08': { f: 'A true boiling point curve is the crude\u2019s fingerprint: cumulative volume distilled against temperature. Cutting it at chosen temperatures gives the yield of each product, and the mid-boiling point of each cut, with its gravity, gives the Watson factor and hence every physical property the downstream units need. The whole refinery configuration argument starts from where you place those cuts.', s: [
 ['V', 'cumulative volume distilled, %'], ['T', 'temperature on the TBP curve, \u00b0C'],
 ['T_{50}', 'the 50 % point of the curve \u2014 the crude\u2019s centre of gravity'],
 ['\\beta', 'the shape parameter of the fitted distribution'],
 ['T_{start},\\ T_{end}', 'the cut points defining a product'],
 ['Y_{cut}', 'volume yield of the cut, % of crude'],
 ['T_{B,cut}', 'mean average boiling point of the cut, \u00b0C'],
 ['\\gamma_{cut}', 'specific gravity of the cut'],
 ['API', 'API gravity of the cut'],
 ['K_{UOP}', 'Watson characterisation factor of the cut'] ] },
'T-09': { f: 'Octane does not blend linearly and everyone pretends it does. The linear volume average is the starting point, but real blends deviate because components interact \u2014 an aromatic in a paraffinic base behaves differently than in an olefinic one \u2014 so an interaction term is added pairwise. Vapour pressure blends on its own index too, and the two constraints usually fight: the component that lifts your octane is often the one that blows your RVP limit.', s: [
 ['RON_{mix}', 'blend research octane number'],
 ['N_i', 'octane number of component i'], ['v_i,\\ v_j', 'volume fractions'],
 ['k_{ij}', 'interaction coefficient between components i and j'],
 ['AKI', 'anti-knock index, the average of RON and MON \u2014 the number on the pump'],
 ['RVP_{mix},\\ P_i', 'blend and component Reid vapour pressure, kPa'],
 ['CI_{mix}', 'blend cetane index for diesel'],
 ['I_i', 'the blending index of component i'] ] },
'T-10': { f: 'Joback estimation is pure bookkeeping over molecular structure: count each functional group, multiply by its tabulated contribution, and add. The boiling point comes first, then the critical constants which depend on it, and the ideal-gas heat capacity comes out as a temperature polynomial from the same counts. Accuracy is good for hydrocarbons and mediocre for strongly hydrogen-bonding molecules \u2014 the groups do not know their neighbours.', s: [
 ['N_k', 'number of times group k appears in the molecule'],
 ['T_b', 'normal boiling point, K'], ['T_c', 'critical temperature, K'],
 ['P_c', 'critical pressure, bar'], ['V_c', 'critical volume, cm\u00b3/mol'],
 ['N_A', 'number of atoms in the molecule \u2014 it enters the P_c correlation'],
 ['\\Delta T_{b,k},\\ \\Delta T_{c,k}', 'group contributions to boiling and critical temperature'],
 ['c_p^{ig}', 'ideal-gas heat capacity as a cubic polynomial in T, J/mol\u00b7K'],
 ['a,\\ b,\\ c,\\ d', 'the four polynomial coefficients, each a sum of group contributions'] ] },
'E-01': { f: 'Vessel volume as a function of level is a geometry problem, and the heads are what make it interesting. A horizontal vessel\u2019s shell contributes a circular-segment area that varies non-linearly with depth, so the same centimetre of level means very different volumes at the bottom, the middle and the top. That is why a horizontal drum\u2019s level transmitter needs a strapping table and a vertical one does not.', s: [
 ['V_{shell}', 'liquid volume in the cylindrical shell, m\u00b3'],
 ['V_{head}', 'liquid volume in one head, m\u00b3'],
 ['V_{vert}', 'liquid volume in a vertical vessel, m\u00b3'],
 ['L', 'tangent-to-tangent shell length, m'], ['R', 'vessel internal radius, m'],
 ['h', 'liquid depth from the bottom of the vessel, m'],
 ['A_{seg}', 'area of the circular segment filled with liquid, m\u00b2'],
 ['a', 'head depth (the distance the head projects beyond the tangent line), m'],
 ['x', 'dimensionless fill, h/2R'],
 ['\\rho', 'liquid density, for converting volume into inventory mass'] ] },
'E-02': { f: 'ASME VIII Division 1 thickness is a hoop-stress balance with two adjustments: the joint efficiency, which penalises you for welds that were not fully radiographed, and the corrosion allowance, which is thickness you agree in advance to lose. Run the same formula the other way with the thickness you actually have and you get the MAWP \u2014 the number stamped on the nameplate and the one every relief calculation is referenced to.', s: [
 ['t_{cyl}', 'required cylindrical shell thickness, mm'],
 ['t_{sph}', 'required spherical (hemispherical head) thickness, mm'],
 ['t_{ell}', 'required 2:1 ellipsoidal head thickness, mm'],
 ['t_{FD}', 'required torispherical (flanged and dished) head thickness, mm'],
 ['P', 'internal design pressure, MPa'], ['R', 'inside radius, mm'], ['D', 'inside diameter, mm'],
 ['S', 'maximum allowable stress for the material at design temperature, MPa'],
 ['E', 'joint efficiency \u2014 1.0 fully radiographed, 0.85 spot, 0.7 none'],
 ['L_c', 'crown radius of a torispherical head, mm'],
 ['MAWP', 'maximum allowable working pressure the built vessel can hold'] ] },
'E-03': { f: 'A separator is two designs sharing a shell. The vapour space is sized by droplet settling \u2014 the Souders\u2013Brown velocity is where drag balances the weight of the smallest droplet you intend to catch \u2014 and that fixes the diameter. The liquid space is sized by time: hold-up for steady operation plus surge for upsets, and that fixes the length. The two rarely give the same aspect ratio, and the longer one wins.', s: [
 ['u_{max}', 'maximum vapour velocity for droplet disengagement, m/s'],
 ['K', 'Souders\u2013Brown coefficient \u2014 0.107 without a mesh pad, higher with one'],
 ['\\rho_l,\\ \\rho_g', 'liquid and vapour density, kg/m\u00b3'],
 ['V_g', 'vapour volumetric flow, m\u00b3/s'],
 ['A_{vap}', 'required vapour cross-sectional area, m\u00b2'],
 ['f_{vap},\\ f_{liq}', 'fraction of the vessel cross-section given to vapour and to liquid'],
 ['D', 'vessel diameter, m'], ['L', 'tangent-to-tangent length, m'],
 ['V_{liq}', 'liquid volume required, m\u00b3'], ['V_l', 'liquid volumetric flow, m\u00b3/s'],
 ['t_{hold}', 'hold-up time for normal control, min'],
 ['t_{surge}', 'surge time for upsets, min'] ] },
'E-04': { f: 'One impeller speed has to satisfy three unrelated duties. Power draw is N_p\u03c1N\u00b3D\u2075, so it climbs with the cube of speed and the fifth power of diameter \u2014 which is why a big slow impeller is cheaper than a small fast one for the same blending. Blend time falls with speed, and the just-suspended speed for solids is fixed by the Zwietering correlation. The design speed is the largest of the three requirements, and the power follows from it.', s: [
 ['P', 'impeller power draw, W'],
 ['N_p', 'power number \u2014 a shape constant, ~5 for a Rushton turbine, ~0.3 for a hydrofoil'],
 ['N', 'impeller speed, rev/s'], ['D', 'impeller diameter, m'], ['T', 'tank diameter, m'],
 ['\\rho,\\ \\mu,\\ \\nu', 'liquid density, dynamic and kinematic viscosity'],
 ['Re', 'impeller Reynolds number, \u03c1ND\u00b2/\u03bc'],
 ['\\theta_{95}', 'time to reach 95 % homogeneity, s'],
 ['N_{js}', 'just-suspended speed \u2014 below it solids sit on the bottom, rev/s'],
 ['S', 'Zwietering geometry constant'],
 ['d_p', 'particle diameter, m'], ['\\Delta\\rho', 'solid-to-liquid density difference'],
 ['X', 'solids loading, % by mass'],
 ['N_q', 'flow number'], ['Q_p', 'impeller pumping capacity, m\u00b3/s'], ['V', 'liquid volume, m\u00b3'] ] },
'E-05': { f: 'API 520 sizes a relief orifice from the choked-flow equation and then applies a string of correction factors, each for one thing that stops the valve behaving ideally: back pressure, rupture disc in series, superheat, viscosity. The area you calculate is then rounded up to the next standard lettered orifice, which is why the installed valve is almost always oversized \u2014 and oversizing is what makes valves chatter.', s: [
 ['A', 'required effective discharge area, mm\u00b2'],
 ['W', 'required relieving mass flow, kg/h'], ['Q', 'required relieving volumetric flow for liquids'],
 ['C', 'the gas coefficient built from the ratio of specific heats'],
 ['K_d', 'effective discharge coefficient \u2014 0.975 for a vapour valve'],
 ['K_b', 'back-pressure correction factor'], ['K_c', 'combination factor for a rupture disc upstream'],
 ['K_w', 'back-pressure correction for liquid service'], ['K_v', 'viscosity correction factor'],
 ['K_N', 'Napier correction for high-pressure steam'], ['K_{SH}', 'steam superheat correction'],
 ['P_1,\\ P_2', 'relieving pressure and back pressure, kPa absolute'],
 ['P_{cf}', 'critical flow pressure \u2014 above this the flow is choked'],
 ['T', 'relieving temperature, K'], ['Z', 'compressibility at relieving conditions'],
 ['M', 'molar mass'], ['k', 'ratio of specific heats'], ['G', 'liquid specific gravity'] ] },
'E-06': { f: 'A fixed-roof tank breathes. Working losses happen when liquid is pumped in and vapour is displaced out; standing losses happen when the sun heats the vapour space and it expands, then contracts overnight and draws fresh air in to be saturated again. AP-42 puts numbers on both. The two together are what a vapour recovery unit or an internal floating roof is justified against.', s: [
 ['L_S', 'standing (breathing) loss, kg/year'], ['L_W', 'working loss, kg/year'],
 ['V_V', 'vapour space volume, m\u00b3'], ['W_V', 'vapour density, kg/m\u00b3'],
 ['K_E', 'vapour space expansion factor \u2014 the daily temperature and pressure swing'],
 ['K_S', 'vented vapour saturation factor'],
 ['\\Delta T_V', 'daily vapour temperature range, K'],
 ['T_{LA}', 'daily average liquid surface temperature, K'],
 ['P_{VA}', 'vapour pressure at that temperature, kPa'],
 ['P_A', 'atmospheric pressure'], ['P_B', 'breather vent setting'],
 ['H_{VO}', 'vapour space outage \u2014 the effective height of the empty space, m'],
 ['M_V', 'vapour molar mass'], ['Q', 'annual throughput, m\u00b3/year'],
 ['K_N', 'turnover factor'], ['K_P', 'working loss product factor'] ] },
'E-07': { f: 'Cutting a hole in a pressure shell removes metal that was carrying load, and the code\u2019s answer is simple bookkeeping: whatever area you removed must be put back within a defined zone around the opening. The nozzle neck contributes, the excess shell thickness contributes, the weld contributes \u2014 and if the total still falls short you add a reinforcing pad. The whole calculation is one inequality: area available must exceed area required.', s: [
 ['A', 'area of reinforcement required, mm\u00b2 \u2014 the metal the hole removed'],
 ['A_1', 'area available in the shell from excess thickness'],
 ['A_2', 'area available in the nozzle neck from its excess thickness'],
 ['d', 'finished opening diameter, mm'],
 ['t', 'actual shell thickness, mm'], ['t_r', 'required shell thickness for pressure, mm'],
 ['t_n', 'actual nozzle wall thickness, mm'], ['t_{rn}', 'required nozzle thickness, mm'],
 ['F', 'correction factor for the plane under consideration \u2014 1.0 for a radial nozzle'],
 ['f_{r1},\\ f_{r2}', 'strength reduction ratios when the nozzle material is weaker than the shell'],
 ['E_1', 'joint efficiency where the opening passes through a weld'],
 ['P', 'design pressure'], ['R,\\ R_n', 'shell and nozzle inside radius'],
 ['S,\\ S_n', 'shell and nozzle allowable stress'] ] },
'E-08': { f: 'A cyclone separates by making the gas turn: the particles cannot follow the streamline and are thrown to the wall. The cut size falls with the number of effective turns and rises with the inlet area, so a small, tall, fast cyclone collects finer dust \u2014 and costs pressure drop as the square of inlet velocity. That trade is the entire cyclone design: every improvement in collection is bought with fan power.', s: [
 ['d_{50}', 'cut size \u2014 the particle diameter collected with 50 % efficiency, \u00b5m'],
 ['\\eta_i', 'grade efficiency \u2014 the fraction of size cut i that is collected'],
 ['d_i', 'diameter of size cut i, \u00b5m'],
 ['N_e', 'number of effective turns the gas makes in the body'],
 ['V_i', 'gas velocity at the inlet, m/s'],
 ['W', 'inlet width, m'], ['H', 'inlet height, m'],
 ['D_e', 'gas outlet (vortex finder) diameter, m'],
 ['L_b,\\ L_c', 'barrel and cone length, m'],
 ['\\rho_p,\\ \\rho', 'particle and gas density'], ['\\mu', 'gas viscosity, Pa\u00b7s'],
 ['\\Delta P', 'pressure drop across the cyclone, Pa'],
 ['N_H', 'pressure drop expressed as inlet velocity heads'] ] },
'U-01': { f: 'A cooling tower loses water three ways and only one of them is useful. Evaporation is the cooling itself \u2014 about 1.8 litres per hour per kW rejected. Drift is mechanical carry-over from the fan. Blowdown is deliberate: because evaporation leaves the dissolved salts behind, you must throw some water away to stop them concentrating, and how much depends entirely on the cycles of concentration you are prepared to run.', s: [
 ['E', 'evaporation rate, m\u00b3/h \u2014 fixed by the duty, not by the design'],
 ['Q', 'heat rejected by the tower, kW'],
 ['h_{fg}', 'latent heat of vaporisation of water, kJ/kg'],
 ['\\rho', 'water density'],
 ['C', 'cycles of concentration \u2014 dissolved solids in the circuit divided by those in the make-up'],
 ['B', 'blowdown rate, m\u00b3/h \u2014 what you purge to hold C'],
 ['D', 'drift loss, m\u00b3/h \u2014 droplets carried out by the fan, typically 0.002 % of circulation'],
 ['M', 'make-up water required, E + B + D'] ] },
'U-02': { f: 'Recycle is how a plant turns a poor single-pass conversion into a high overall one, and purge is the price. Anything inert that enters with the feed cannot leave with the product, so it accumulates in the loop until the purge removes it as fast as it arrives. A small purge means a high recycle inert concentration and a large recycle compressor; a large purge throws away reactant. Where those two costs cross is the design.', s: [
 ['F', 'fresh feed rate to the process'],
 ['z_I', 'inert mole fraction in the fresh feed \u2014 the source of the whole problem'],
 ['y_I', 'inert mole fraction in the recycle loop at steady state'],
 ['P_{purge}', 'purge stream flow \u2014 what leaves to keep y_I from running away'],
 ['X_{pass}', 'single-pass conversion \u2014 what the reactor achieves in one go'],
 ['X_{ov}', 'overall conversion \u2014 what the plant achieves including recycle'],
 ['\\alpha', 'recycle ratio \u2014 recycle flow divided by fresh feed'] ] },
'U-03': { f: 'Capital estimating is three multiplications. The six-tenths rule scales a known cost to a different size, because equipment cost rises more slowly than capacity. A cost index moves that number from the year it was quoted to today. Then the bare-module factor multiplies the equipment cost up to an installed cost, taking in piping, instruments, foundations, electrical and erection \u2014 typically a factor of three to four for a fluid-service plant.', s: [
 ['C_1,\\ C_2', 'known cost at size A\u2081 and estimated cost at size A\u2082'],
 ['A_1,\\ A_2', 'the capacity or size measure of each'],
 ['n', 'scaling exponent \u2014 0.6 is the default; it is 0.4\u20130.9 depending on the item'],
 ['C_{base}', 'cost in the base year'], ['C_{now}', 'cost escalated to today'],
 ['CEPI_{base},\\ CEPI_{now}', 'chemical engineering plant cost index then and now'],
 ['C_p', 'purchased equipment cost at base conditions'],
 ['F_M', 'material factor \u2014 1 for carbon steel, 2\u20134 for stainless and alloys'],
 ['F_P', 'pressure factor'], ['F_{BM}', 'bare-module factor combining installation, material and pressure'],
 ['C_{BM}', 'bare-module (installed) cost'] ] },
'U-04': { f: 'Every conversion goes through the SI base unit rather than directly between the two units you named. Multiply by the source factor to get to SI, divide by the target factor to leave it \u2014 one table of factors instead of a table of every possible pair, and no chance of the two directions disagreeing. Temperature is the exception, because its scales have offsets as well as slopes.', s: [
 ['\\text{value}_{SI}', 'the quantity expressed in the SI base unit for its dimension'],
 ['\\text{factor}_{from}', 'multiplier converting the source unit into SI'],
 ['\\text{factor}_{to}', 'multiplier converting the target unit into SI \u2014 divided out at the end'] ] }
});
